 9: use App\Notifications\CustomerPasswordReset;
10: use Illuminate\Support\Facades\Http;
11: 
12: class CustomerSmsChannel
13: {
14:     public function send(Customer $customer, CustomerPasswordReset $notification): void
15:     {
16:         $url = config('services.customer_sms.url');
17:         $token = config('services.customer_sms.token');
18:         if (! is_string($url) || ! str_starts_with($url, 'https://') || ! is_string($token) || $token === '') {
19:             throw new BusinessException('خدمة الرسائل النصية غير مهيأة حاليًا.', [], 503);
20:         }
21: 
22:         Http::withToken($token)->connectTimeout(3)->timeout(10)->post($url, [
23:             'to' => $customer->phone,
24:             'message' => $notification->toSms($customer),
25:         ])->throw();
26:     }
27: } 1: <?php
