  5: namespace App\Http\Controllers\Api\V1\Admin;
  6: 
  7: use App\Enums\CustomerDocumentStatus;
  8: use App\Enums\CustomerStatus;
  9: use App\Enums\CustomerType;
 10: use App\Http\Controllers\Controller;
 11: use App\Http\Requests\Admin\Customer\ApproveCustomerRequest;
 12: use App\Http\Requests\Admin\Customer\RejectCustomerRequest;
 13: use App\Http\Requests\Admin\Customer\StoreCustomerRequest;
 14: use App\Http\Requests\Admin\Customer\SuspendCustomerRequest;
 15: use App\Http\Requests\Admin\Customer\UpdateCustomerRequest;
 16: use App\Http\Resources\Admin\CustomerResource;
 17: use App\Models\Customer;
 18: use App\Models\CustomerDocument;
 19: use App\Services\CustomerManagementService;
 20: use Illuminate\Http\JsonResponse;
 21: use Illuminate\Http\Request;
 22: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 23: use Illuminate\Routing\Controllers\HasMiddleware;
 24: use Illuminate\Routing\Controllers\Middleware;
 25: use Illuminate\Support\Facades\Storage;
 26: use Illuminate\Validation\Rule;
 27: use Symfony\Component\HttpFoundation\StreamedResponse;
 28: 
 29: /** إدارة العملاء واعتماد حسابات الجملة في لوحة الإدارة. */
 30: class CustomerController extends Controller implements HasMiddleware
 31: {
 32:     public function __construct(private readonly CustomerManagementService $customers) {}
 33: 
 34:     public static function middleware(): array
 35:     {
 36:         return [
 37:             new Middleware('can:customers.view', only: ['index', 'show', 'downloadDocument']),
 38:             new Middleware('can:customers.create', only: ['store']),
 39:             new Middleware('can:customers.update', only: ['update']),
 40:             new Middleware('can:customers.delete', only: ['destroy', 'restore']),
 41:             new Middleware('can:customers.approve', only: ['approve', 'reject', 'suspend', 'reviewDocument']),
 42:         ];
 43:     }
 44: 
 45:     public function index(Request $request): AnonymousResourceCollection
 46:     {
 47:         $filters = $request->validate([
 48:             'type' => ['nullable', Rule::in(array_column(CustomerType::cases(), 'value'))],
 49:             'status' => ['nullable', Rule::in(array_column(CustomerStatus::cases(), 'value'))],
 50:             'customer_group_id' => ['nullable', 'integer', 'min:1'],
 51:             'search' => ['nullable', 'string', 'max:255'],
 52:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 53:             'trashed' => ['nullable', Rule::in(['only'])],
 54:         ]);
 55: 
 56:         return CustomerResource::collection($this->customers->paginate($filters));
 57:     }
 58: 
 59:     public function store(StoreCustomerRequest $request): JsonResponse
 60:     {
 61:         $customer = $this->customers->create($request->validated());
 62: 
 63:         return CustomerResource::make($customer)
 64:             ->additional(['message' => 'تم إنشاء العميل بنجاح'])
 65:             ->response()
 66:             ->setStatusCode(201);
 67:     }
 68: 
 69:     public function show(Customer $customer): CustomerResource
 70:     {
 71:         return new CustomerResource($this->customers->find($customer->id));
 72:     }
 73: 
 74:     public function update(UpdateCustomerRequest $request, Customer $customer): CustomerResource
 75:     {
 76:         return new CustomerResource($this->customers->update($customer, $request->validated()));
 77:     }
 78: 
 79:     public function destroy(Customer $customer): JsonResponse
 80:     {
 81:         $this->customers->delete($customer);
 82: 
 83:         return response()->json(['message' => 'تم حذف العميل بنجاح']);
 84:     }
 85: 
 86:     public function approve(ApproveCustomerRequest $request, Customer $customer): CustomerResource
 87:     {
 88:         $customer = $this->customers->approve($customer, $request->validated(), $request->user()->id);
 89: 
 90:         return (new CustomerResource($customer))->additional(['message' => 'تم اعتماد الحساب بنجاح']);
 91:     }
 92: 
 93:     public function reject(RejectCustomerRequest $request, Customer $customer): CustomerResource
 94:     {
 95:         $customer = $this->customers->reject($customer, $request->validated()['reason']);
 96: 
 97:         return (new CustomerResource($customer))->additional(['message' => 'تم رفض الحساب']);
 98:     }
 99: 
100:     public function suspend(SuspendCustomerRequest $request, Customer $customer): CustomerResource
101:     {
102:         $customer = $this->customers->suspend($customer, $request->validated()['reason']);
103: 
104:         return (new CustomerResource($customer))->additional(['message' => 'تم إيقاف الحساب وإنهاء جلساته']);
105:     }
106: 
107:     /** تنزيل مستند تحقق من التخزين الخاص (scoped: المستند تابع لهذا العميل حصرًا). */
108:     public function downloadDocument(Customer $customer, CustomerDocument $document): StreamedResponse
109:     {
110:         abort_unless(Storage::disk('local')->exists($document->file_path), 404, 'المستند غير موجود.');
111: 
112:         return Storage::disk('local')->download($document->file_path, CustomerDocument::safeName($document->original_name));
113:     }
114: 
115:     public function restore(Customer $customer): CustomerResource
116:     {
117:         abort_unless($customer->trashed(), 422, 'الحساب غير محذوف.');
118:         $customer->restore();
119: 
120:         return new CustomerResource($customer->load('customerGroup'));
121:     }
122: 
123:     public function reviewDocument(Request $request, Customer $customer, CustomerDocument $document): JsonResponse
124:     {
125:         $data = $request->validate([
126:             'status' => ['required', Rule::enum(CustomerDocumentStatus::class)],
127:         ]);
128:         $document->update($data);
129: 
130:         return response()->json(['data' => ['id' => $document->id, 'status' => $document->status]]);
131:     }
132: } 1: <?php
