19: class ProductVariantController extends Controller implements HasMiddleware
20: {
21:     public function __construct(private VariantService $service) {}
22: 
23:     public static function middleware(): array
24:     {
25:         return [
26:             new Middleware('can:products.view', only: ['index', 'show']),
27:             // تعديل المتغيرات معناه تعديل المنتج نفسه
28:             new Middleware('can:products.update', only: ['store', 'update', 'destroy']),
29:         ];
30:     }
31: 
32:     public function index(Product $product): AnonymousResourceCollection
33:     {
34:         return VariantResource::collection($product->variants()->with('media')->get());
35:     }
36: 
37:     public function store(StoreVariantRequest $request, Product $product): JsonResponse
38:     {
39:         $data = $request->validated();
40:         if (! $request->user()->can('products.view_cost')) {
41:             unset($data['cost_price']);
42:         }
43: 
44:         $variant = $this->service->create($product, $data);
45:         $variant->load('media');
46:         $variant->setRelation('product', $product);
47: 
48:         return VariantResource::make($variant)->response()->setStatusCode(201);
49:     }
50: 
51:     public function show(Product $product, ProductVariant $variant): VariantResource
52:     {
53:         $variant->load('media');
54:         $variant->setRelation('product', $product);
55: 
56:         return VariantResource::make($variant);
57:     }
58: 
59:     public function update(UpdateVariantRequest $request, Product $product, ProductVariant $variant): VariantResource
60:     {
61:         $data = $request->validated();
62:         if (! $request->user()->can('products.view_cost')) {
63:             unset($data['cost_price']);
64:         }
65: 
66:         $variant = $this->service->update($variant, $data);
67:         $variant->load('media')->setRelation('product', $product);
68: 
69:         return VariantResource::make($variant);
70:     }
71: 
72:     public function destroy(Product $product, ProductVariant $variant): JsonResponse
73:     {
74:         $this->service->delete($variant);
75: 
76:         return response()->json(['message' => 'تم الحذف']);
77:     }
78: } 1: <?php
