 5: namespace App\Http\Controllers\Api\V1\Store;
 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Http\Requests\Store\ForgotPasswordRequest;
 9: use App\Http\Requests\Store\LoginRequest;
10: use App\Http\Requests\Store\RegisterRequest;
11: use App\Http\Requests\Store\ResetPasswordRequest;
12: use App\Http\Resources\Store\CustomerResource;
13: use App\Services\CustomerAuthService;
14: use Illuminate\Http\JsonResponse;
15: use Illuminate\Http\Request;
16: use Illuminate\Support\Facades\DB;
17: 
18: /** مصادقة المتجر القطاعي: تسجيل فوري معتمد، دخول، خروج، واستعادة كلمة المرور. */
19: class AuthController extends Controller
20: {
21:     public function __construct(private readonly CustomerAuthService $auth) {}
22: 
23:     public function register(RegisterRequest $request): JsonResponse
24:     {
25:         [$customer, $token] = DB::transaction(function () use ($request): array {
26:             $customer = $this->auth->registerRetail($request->validated());
27: 
28:             return [$customer, $this->auth->issueToken($customer, 'store-token')];
29:         });
30: 
31:         return CustomerResource::make($customer)
32:             ->additional(['message' => 'تم إنشاء حسابك بنجاح', 'token' => $token])
33:             ->response()
34:             ->setStatusCode(201);
35:     }
36: 
37:     public function login(LoginRequest $request): CustomerResource
38:     {
39:         $customer = $this->auth->login($request->validated()['login'], $request->validated()['password']);
40:         $token = $this->auth->issueToken($customer, 'store-token');
41: 
42:         return CustomerResource::make($customer)
43:             ->additional(['message' => 'تم تسجيل الدخول بنجاح', 'token' => $token]);
44:     }
45: 
46:     /** خروج: حذف التوكن الحالي فقط (بقية الجلسات على أجهزة أخرى تظل فعالة). */
47:     public function logout(Request $request): JsonResponse
48:     {
49:         $request->user()->currentAccessToken()->delete();
50: 
51:         return response()->json(['message' => 'تم تسجيل الخروج بنجاح']);
52:     }
53: 
54:     public function forgotPassword(ForgotPasswordRequest $request): JsonResponse
55:     {
56:         $this->auth->forgotPassword($request->validated()['email'] ?? null, $request->validated()['phone'] ?? null);
57: 
58:         return response()->json(['message' => 'لو الحساب موجود، أرسلنا رمز الاستعادة إليه.']);
59:     }
60: 
61:     public function resetPassword(ResetPasswordRequest $request): JsonResponse
62:     {
63:         $this->auth->resetPassword($request->validated());
64: 
65:         return response()->json(['message' => 'تم تغيير كلمة المرور؛ سجل الدخول من جديد.']);
66:     }
67: } 1: <?php
