17: /** قوائم التصفح الثابتة: أقسام (شجرة بعدّادات منتجات منشورة) وعلامات ومدن الشحن. */
18: class CatalogController extends Controller
19: {
20:     public function categories(Request $request): JsonResponse
21:     {
22:         $roots = Category::query()
23:             ->whereNull('parent_id')
24:             ->where('is_active', true)
25:             ->with('media')
26:             ->withCount('activeProducts')
27:             ->with([
28:                 'children' => fn ($q) => $q->where('is_active', true)->with('media')->withCount('activeProducts')->orderBy('sort_order')
29:                     ->with(['children' => fn ($q2) => $q2->where('is_active', true)->with('media')->withCount('activeProducts')->orderBy('sort_order')]),
30:             ])
31:             ->orderBy('sort_order')
32:             ->get();
33: 
34:         return response()->json(['data' => StoreCategoryResource::collection($roots)->resolve($request)]);
35:     }
36: 
37:     public function brands(Request $request): JsonResponse
38:     {
39:         $brands = Brand::query()
40:             ->with('media')
41:             ->where('is_active', true)
42:             ->orderBy('sort_order')
43:             ->orderBy('name_ar')
44:             ->get();
45: 
46:         return response()->json(['data' => StoreBrandResource::collection($brands)->resolve($request)]);
47:     }
48: 
49:     public function cities(Request $request): JsonResponse
50:     {
51:         $cities = City::query()
52:             ->where('is_active', true)
53:             ->orderBy('name_ar')
54:             ->get();
55: 
56:         return response()->json(['data' => StoreCityResource::collection($cities)->resolve($request)]);
57:     }
58: } 1: <?php
