 6: 
 7: use App\Http\Controllers\Controller;
 8: use App\Http\Resources\Store\StoreBannerResource;
 9: use App\Http\Resources\Store\StoreProductCardResource;
10: use App\Models\Banner;
11: use App\Services\StoreCatalogService;
12: use Illuminate\Http\JsonResponse;
13: use Illuminate\Http\Request;
14: use Illuminate\Support\Collection;
15: use Illuminate\Support\Facades\Cache;
16: 
17: /**
18:  * الصفحة الرئيسية للمتجر: رد مجمّع واحد (بانرات + أحدث + أكثر مبيعًا + مخفضات).
19:  * الكاش يخزن معرّفات الأقسام فقط (5 دقائق) — الأسعار تُحسب لكل طلب على حدة
20:  * لأنها شخصية (خصم مجموعة/سعر خاص)، فلا تتسرب أسعار عميل لزائر آخر أبدًا.
21:  */
22: class HomeController extends Controller
23: {
24:     public function __construct(private readonly StoreCatalogService $catalog) {}
25: 
26:     public function index(Request $request): JsonResponse
27:     {
28:         $ids = Cache::remember('store_home_data', 300, fn () => $this->catalog->homeSectionIds());
29:         $allIds = array_unique([...$ids['latest_ids'], ...$ids['best_seller_ids'], ...$ids['discounted_ids']]);
30:         $cards = StoreProductCardResource::collection($this->catalog->publishedQuery()
31:             ->whereIn('products.id', $allIds)->get())->resolve($request);
32:         $cards = collect($cards)->keyBy('id');
33:         $section = fn (array $sectionIds) => collect($sectionIds)->map(fn ($id) => $cards->get($id))->filter()->values();
34: 
35:         return response()->json([
36:             'data' => [
37:                 'banners' => StoreBannerResource::collection($this->inOrder(Banner::query()
38:                     ->where('is_active', true)
39:                     ->where(fn ($q) => $q->whereNull('starts_at')->orWhere('starts_at', '<=', now()))
40:                     ->where(fn ($q) => $q->whereNull('ends_at')->orWhere('ends_at', '>=', now())), $ids['banner_ids']))->resolve($request),
41:                 'latest_products' => $section($ids['latest_ids']),
42:                 'best_sellers' => $section($ids['best_seller_ids']),
43:                 'discounted_products' => $section($ids['discounted_ids'])->filter(fn ($card) => $card['price'] !== null && $card['discount_percentage'] !== null)->values(),
44:             ],
45:         ]);
46:     }
47: 
48:     /** @param list<int> $ids */
49:     private function inOrder($query, array $ids): Collection
50:     {
51:         if ($ids === []) {
52:             return collect();
53:         }
54:         $positions = array_flip($ids);
55: 
56:         return $query->whereIn('id', $ids)->get()->sortBy(fn ($m) => $positions[$m->id] ?? PHP_INT_MAX)->values();
57:     }
58: } 1: <?php
