 5: namespace App\Http\Requests\Admin\Concerns;
 6: 
 7: trait NormalizesCatalogInput
 8: {
 9:     protected function normalizeCatalogIdentifiers(): void
10:     {
11:         $changes = [];
12:         foreach (['slug' => 'strtolower', 'sku' => 'strtoupper'] as $field => $normalize) {
13:             if (is_string($value = $this->input($field))) {
14:                 $changes[$field] = $normalize($value);
15:             }
16:         }
17:         if (is_array($variants = $this->input('variants'))) {
18:             foreach ($variants as &$variant) {
19:                 if (is_array($variant) && isset($variant['sku']) && is_string($variant['sku'])) {
20:                     $variant['sku'] = strtoupper($variant['sku']);
21:                 }
22:             }
23:             unset($variant);
24:             $changes['variants'] = $variants;
25:         }
26:         $this->merge($changes);
27:     }
28: } 1: <?php
