 5: namespace App\Http\Resources\Store;
 6: 
 7: use App\Services\StoreCatalogService;
 8: use Illuminate\Http\Request;
 9: use Illuminate\Http\Resources\Json\JsonResource;
10: 
11: /**
12:  * بطاقة منتج في المتجر: السعر النهائي عبر PricingService للعميل الحالي
13:  * (زائر = قناة قطاعي، وعميل بتوكن = مجموعته/أسعاره الخاصة تسرى عليه).
14:  */
15: class StoreProductCardResource extends JsonResource
16: {
17:     /**
18:      * @return array<string, mixed>
19:      */
20:     public function toArray(Request $request): array
21:     {
22:         $service = app(StoreCatalogService::class);
23:         $customer = $service->customer();
24: 
25:         $display = $service->displayPrice($this->resource, $customer);
26: 
27:         $available = $this->store_available !== null
28:             ? (float) $this->store_available
29:             : array_sum($service->availabilityMap($this->variants->pluck('id')->all()));
30: 
31:         return [
32:             'id' => $this->id,
33:             'name_ar' => $this->name_ar,
34:             'name_en' => $this->name_en,
35:             'slug' => $this->slug,
36:             'image' => $this->getFirstMediaUrl('images', 'thumb') ?: ($this->getFirstMediaUrl('images') ?: null),
37:             'brand' => $this->whenLoaded('brand', fn () => $this->brand ? [
38:                 'id' => $this->brand->id, 'name_ar' => $this->brand->name_ar, 'name_en' => $this->brand->name_en, 'slug' => $this->brand->slug,
39:             ] : null),
40:             'category' => $this->whenLoaded('category', fn () => $this->category ? [
41:                 'id' => $this->category->id, 'name_ar' => $this->category->name_ar, 'name_en' => $this->category->name_en, 'slug' => $this->category->slug,
42:             ] : null),
43:             'price' => $display['price'] ?? null,
44:             'old_price' => $display !== null && $display['compare_at'] !== null && $display['compare_at'] > $display['price']
45:                 ? $display['compare_at'] : null,
46:             'discount_percentage' => $display['discount_percentage'] ?? null,
47:             'is_featured' => (bool) $this->is_featured,
48:             'sales_count' => (int) $this->sales_count,
49:             'store_available' => $available,
50:             'in_stock' => $available > 0,
51:         ];
52:     }
53: } 1: <?php
