 5: namespace App\Http\Resources\Store;
 6: 
 7: use App\Exceptions\BusinessException;
 8: use App\Services\StoreCatalogService;
 9: use Illuminate\Http\Request;
10: use Illuminate\Http\Resources\Json\JsonResource;
11: 
12: /** صفحة منتج كاملة: كل متغير بسعره النهائي ومتاحه أونلاين. */
13: class StoreProductResource extends JsonResource
14: {
15:     /**
16:      * خريطة متاح المتغيرات (يضبطها المتحكم من StoreCatalogService).
17:      *
18:      * @var array<int, float>
19:      */
20:     public array $availability = [];
21: 
22:     /**
23:      * @return array<string, mixed>
24:      */
25:     public function toArray(Request $request): array
26:     {
27:         $pricing = app(StoreCatalogService::class);
28:         $customer = $pricing->customer();
29: 
30:         $card = (new StoreProductCardResource($this->resource))->resolve($request);
31: 
32:         return [
33:             ...$card,
34:             'description_ar' => $this->description_ar,
35:             'description_en' => $this->description_en,
36:             'material_ar' => $this->material_ar,
37:             'material_en' => $this->material_en,
38:             'warranty_months' => $this->warranty_months,
39:             'country_of_origin' => $this->country_of_origin,
40:             'images' => $this->getMedia('images')->map(fn ($media) => [
41:                 'id' => $media->id,
42:                 'url' => $media->getUrl(),
43:                 'thumb' => $media->getUrl('thumb'),
44:             ])->all(),
45:             'variants' => $this->variants->map(function ($variant) use ($pricing, $customer) {
46:                 $resolved = null;
47:                 try {
48:                     $resolved = $pricing->variantPrice($variant, $customer);
49:                 } catch (BusinessException) {
50:                     // متغير غير مُسعَّر: يظهر بلا سعر بدل كسر صفحة المنتج
51:                 }
52:                 $available = (float) ($this->availability[$variant->id] ?? 0);
53: 
54:                 return [
55:                     'id' => $variant->id,
56:                     'sku' => $variant->sku,
57:                     'color_name_ar' => $variant->color_name_ar,
58:                     'color_name_en' => $variant->color_name_en,
59:                     'color_hex' => $variant->color_hex,
60:                     'size' => $variant->size,
61:                     'capacity' => $variant->capacity,
62:                     'price' => $resolved !== null ? (float) $resolved['unit_price'] : null,
63:                     'old_price' => $resolved !== null && max((float) $variant->compare_at_price, (float) $resolved['base_price']) > (float) $resolved['unit_price']
64:                         ? max((float) $variant->compare_at_price, (float) $resolved['base_price']) : null,
65:                     'available' => $available,
66:                     'in_stock' => $available > 0,
67:                 ];
68:             })->all(),
69:         ];
70:     }
71: } 1: <?php
