  7: use App\Enums\CustomerStatus;
  8: use App\Enums\CustomerType;
  9: use App\Exceptions\BusinessException;
 10: use App\Jobs\SendCustomerPasswordReset;
 11: use App\Models\Customer;
 12: use App\Notifications\Channels\CustomerSmsChannel;
 13: use App\Notifications\CustomerPasswordReset;
 14: use Illuminate\Support\Facades\DB;
 15: use Illuminate\Support\Facades\Hash;
 16: use Illuminate\Support\Str;
 17: 
 18: /**
 19:  * دورة مصادقة العملاء (متجر قطاعي + جملة): التسجيل، الدخول، واستعادة كلمة المرور.
 20:  * القيم الحساسة (type/status) تُفرض هنا برمجيًا ولا تأتي من الطلب أبدًا.
 21:  */
 22: class CustomerAuthService
 23: {
 24:     /** تسجيل متجر قطاعي: نوع retail وحالة approved دائمًا. */
 25:     public function registerRetail(array $data): Customer
 26:     {
 27:         return Customer::query()->create([
 28:             'name' => $data['name'],
 29:             'email' => $data['email'] ?? null,
 30:             'phone' => $data['phone'],
 31:             'password' => $data['password'],
 32:             'type' => CustomerType::Retail,
 33:             'status' => CustomerStatus::Approved,
 34:         ]);
 35:     }
 36: 
 37:     /**
 38:      * دخول بالهاتف أو البريد. الحساب الموقوف يُرفض 403 بسبب الإيقاف؛
 39:      * أي حالة أخرى (بما فيها pending/rejected للجملة) تستطيع الدخول —
 40:      * بوابات النوع والحالة (wholesale.approved) تحكم ما بعد الدخول.
 41:      */
 42:     public function login(string $identifier, string $password): Customer
 43:     {
 44:         $identifier = mb_strtolower(trim($identifier));
 45:         $customer = Customer::query()
 46:             ->where(fn ($q) => $q->whereRaw('LOWER(email) = ?', [$identifier])->orWhere('phone', $identifier))
 47:             ->first();
 48: 
 49:         if ($customer === null || ! Hash::check($password, $customer->password)) {
 50:             throw new BusinessException('بيانات الدخول غير صحيحة.', [], 401);
 51:         }
 52: 
 53:         if ($customer->status === CustomerStatus::Suspended) {
 54:             throw new BusinessException(
 55:                 'هذا الحساب موقوف.'.($customer->suspension_reason ? ' السبب: '.$customer->suspension_reason : ''),
 56:                 ['suspension_reason' => $customer->suspension_reason],
 57:                 403,
 58:             );
 59:         }
 60: 
 61:         return $customer;
 62:     }
 63: 
 64:     /**
 65:      * استعادة كلمة المرور: رمز في password_reset_tokens + إشعار للعميل.
 66:      * الرد واحد دائمًا (نجاح ظاهري) حتى لا يُستدل على وجود الحساب.
 67:      */
 68:     public function forgotPassword(?string $email, ?string $phone): void
 69:     {
 70:         if (! $email && ! $phone) {
 71:             return;
 72:         }
 73: 
 74:         SendCustomerPasswordReset::dispatch($email, $phone)
 75:             ->onConnection(config('auth.customer_password_reset.connection', 'database'));
 76:     }
 77: 
 78:     public function sendPasswordReset(?string $email, ?string $phone): void
 79:     {
 80:         if (! $email && ! $phone) {
 81:             return;
 82:         }
 83: 
 84:         $customer = Customer::query()
 85:             ->when($email, fn ($q) => $q->whereRaw('LOWER(email) = ?', [mb_strtolower(trim($email))]),
 86:                 fn ($q) => $q->where('phone', trim($phone)))
 87:             ->first();
 88: 
 89:         if ($customer === null || $customer->status === CustomerStatus::Suspended) {
 90:             return;
 91:         }
 92: 
 93:         $plainToken = Str::random(64);
 94:         $key = $customer->getEmailForPasswordReset();
 95: 
 96:         $stored = DB::transaction(function () use ($customer, $key, $plainToken): bool {
 97:             $current = Customer::query()->lockForUpdate()->find($customer->id);
 98:             if ($current === null || $current->status === CustomerStatus::Suspended) {
 99:                 return false;
100:             }
101:             $existing = DB::table('password_reset_tokens')->where('email', $key)->first();
102:             if ($existing && now()->subSeconds(60)->lt($existing->created_at)) {
103:                 return false;
104:             }
105:             DB::table('password_reset_tokens')->updateOrInsert(
106:                 ['email' => $key], ['token' => Hash::make($plainToken), 'created_at' => now()],
107:             );
108: 
109:             return true;
110:         });
111:         if (! $stored) {
112:             return;
113:         }
114: 
115:         try {
116:             $customer->notify(new CustomerPasswordReset($plainToken, $email ? 'mail' : CustomerSmsChannel::class));
117:         } catch (\Throwable $exception) {
118:             report($exception);
119:         }
120:     }
121: 
122:     public function resetPassword(array $data): void
123:     {
124:         DB::transaction(function () use ($data): void {
125:             $customer = Customer::query()
126:                 ->when(! empty($data['email']), fn ($q) => $q->whereRaw('LOWER(email) = ?', [$data['email']]),
127:                     fn ($q) => $q->where('phone', $data['phone']))
128:                 ->lockForUpdate()->first();
129:             $key = $customer?->getEmailForPasswordReset();
130:             $row = DB::table('password_reset_tokens')->where('email', $key)->lockForUpdate()->first();
131:             if ($customer === null || $customer->status === CustomerStatus::Suspended || $row === null
132:                 || $row->created_at === null || now()->subMinutes(60)->gte($row->created_at)
133:                 || now()->lt($row->created_at) || ! Hash::check($data['token'], $row->token)) {
134:                 throw new BusinessException('رمز الاستعادة غير صالح أو انتهت صلاحيته.');
135:             }
136:             $customer->update(['password' => $data['password'], 'remember_token' => Str::random(60)]);
137:             $customer->tokens()->delete();
138:             DB::table('password_reset_tokens')->where('email', $key)->delete();
139:         });
140:     }
141: 
142:     /** إصدار توكن Sanctum باسم القناة (store-token / wholesale-token). */
143:     public function issueToken(Customer $customer, string $name): string
144:     {
145:         return DB::transaction(function () use ($customer, $name): string {
146:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
147:             if ($customer->status === CustomerStatus::Suspended) {
148:                 throw new BusinessException('هذا الحساب موقوف.', [], 403);
149:             }
150: 
151:             return $customer->createToken($name)->plainTextToken;
152:         });
153:     }
154: }  1: <?php
