  5: namespace App\Services;
  6: 
  7: use App\Enums\CustomerStatus;
  8: use App\Enums\CustomerType;
  9: use App\Exceptions\BusinessException;
 10: use App\Models\Customer;
 11: use Illuminate\Contracts\Pagination\LengthAwarePaginator;
 12: use Illuminate\Support\Facades\DB;
 13: 
 14: /**
 15:  * إدارة العملاء من لوحة الإدارة: CRUD + دورة اعتماد الجملة (اعتماد/رفض/إيقاف).
 16:  * الإيقاف يقتل كل جلسات العميل فورًا؛ الرفض يبقي توكنه حيًا حتى يطّلع على
 17:  * سبب الرفض ومستنداته المرفوضة عبر application-status.
 18:  */
 19: class CustomerManagementService
 20: {
 21:     public function paginate(array $filters): LengthAwarePaginator
 22:     {
 23:         return Customer::query()
 24:             ->with('customerGroup')
 25:             ->when(($filters['trashed'] ?? null) === 'only', fn ($q) => $q->onlyTrashed())
 26:             ->when($filters['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
 27:             ->when($filters['status'] ?? null, fn ($q, $v) => $q->where('status', $v))
 28:             ->when($filters['customer_group_id'] ?? null, fn ($q, $v) => $q->where('customer_group_id', $v))
 29:             ->when($filters['search'] ?? null, function ($q, $v): void {
 30:                 $term = '%'.SearchTerm::escape($v).'%';
 31:                 $q->whereLike('search_text', $term, caseSensitive: false);
 32:             })
 33:             ->orderByDesc('id')
 34:             ->paginate($filters['per_page'] ?? 15);
 35:     }
 36: 
 37:     public function find(int $id): Customer
 38:     {
 39:         return Customer::query()
 40:             ->with(['customerGroup', 'documents', 'addresses.city', 'approver'])
 41:             ->findOrFail($id);
 42:     }
 43: 
 44:     public function create(array $data): Customer
 45:     {
 46:         $data['type'] ??= CustomerType::Retail->value;
 47:         $data['credit_limit'] ??= 0;
 48:         // الحالة الافتراضية حسب النوع ما لم تُرسل صراحة: قطاعي معتمد، جملة/موزع قيد المراجعة
 49:         $data['status'] ??= ($data['type'] ?? CustomerType::Retail->value) === CustomerType::Retail->value
 50:             ? CustomerStatus::Approved
 51:             : CustomerStatus::Pending;
 52: 
 53:         if ($data['status'] === CustomerStatus::Approved || $data['status'] === CustomerStatus::Approved->value) {
 54:             if ($data['type'] !== CustomerType::Retail->value) {
 55:                 throw new BusinessException('أنشئ حساب الجملة قيد المراجعة ثم استخدم مسار الاعتماد.');
 56:             }
 57:         }
 58: 
 59:         return Customer::query()->create($data)->load('customerGroup');
 60:     }
 61: 
 62:     public function update(Customer $customer, array $data): Customer
 63:     {
 64:         return DB::transaction(function () use ($customer, $data): Customer {
 65:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
 66:             if (isset($data['type']) && $data['type'] !== $customer->type->value) {
 67:                 throw new BusinessException('تغيير نوع الحساب المعتمد يتطلب استخدام مسار الاعتماد.');
 68:             }
 69:             if ($customer->status === CustomerStatus::Approved && $customer->type !== CustomerType::Retail) {
 70:                 foreach (['company_name', 'tax_number', 'commercial_register'] as $field) {
 71:                     if (array_key_exists($field, $data) && blank($data[$field])) {
 72:                         throw new BusinessException('لا يمكن مسح بيانات الجملة لحساب معتمد.', [$field => ['هذا الحقل مطلوب.']]);
 73:                     }
 74:                 }
 75:             }
 76:             $customer->update($data);
 77: 
 78:             return $customer->load('customerGroup');
 79:         });
 80:     }
 81: 
 82:     /** حذف ناعم + إنهاء الجلسات: حساب محذوف لا يبقى مسجلًا دخوله. */
 83:     public function delete(Customer $customer): void
 84:     {
 85:         DB::transaction(function () use ($customer): void {
 86:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
 87:             $customer->tokens()->delete();
 88:             $customer->delete();
 89:         });
 90:     }
 91: 
 92:     /**
 93:      * اعتماد حساب (غالبًا طلب جملة): يطبق اختياريًا المجموعة والحد الائتماني
 94:      * والترقية لموزع، ويسجل المعتمِد ووقته، ويمسح أي سبب رفض/إيقاف سابق.
 95:      */
 96:     public function approve(Customer $customer, array $data, int $adminId): Customer
 97:     {
 98:         return DB::transaction(function () use ($customer, $data, $adminId): Customer {
 99:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
100:             if ($customer->status === CustomerStatus::Approved && ($data['type'] ?? $customer->type->value) === $customer->type->value) {
101:                 throw new BusinessException('هذا الحساب معتمد بالفعل.');
102:             }
103:             $legal = [];
104:             if (($data['type'] ?? $customer->type->value) !== CustomerType::Retail->value) {
105:                 foreach (['company_name', 'tax_number', 'commercial_register'] as $field) {
106:                     $legal[$field] = $data[$field] ?? $customer->{$field};
107:                     if (blank($legal[$field])) {
108:                         throw new BusinessException('بيانات الجملة مطلوبة قبل الاعتماد.', [$field => ['هذا الحقل مطلوب لاعتماد حساب الجملة أو الموزع.']]);
109:                     }
110:                 }
111:             }
112: 
113:             $customer->update([
114:                 ...$legal,
115:                 'status' => CustomerStatus::Approved,
116:                 'approved_by' => $adminId,
117:                 'approved_at' => now(),
118:                 'rejection_reason' => null,
119:                 'suspension_reason' => null,
120:                 'customer_group_id' => array_key_exists('customer_group_id', $data) ? $data['customer_group_id'] : $customer->customer_group_id,
121:                 'credit_limit' => $data['credit_limit'] ?? $customer->credit_limit,
122:                 'type' => $data['type'] ?? $customer->type,
123:             ]);
124: 
125:             return $customer->load(['customerGroup', 'documents']);
126:         });
127:     }
128: 
129:     public function reject(Customer $customer, string $reason): Customer
130:     {
131:         return DB::transaction(function () use ($customer, $reason): Customer {
132:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
133:             if ($customer->status !== CustomerStatus::Pending) {
134:                 throw new BusinessException('يمكن رفض الطلبات قيد المراجعة فقط؛ استخدم الإيقاف للحسابات المعتمدة.');
135:             }
136: 
137:             $customer->update([
138:                 'status' => CustomerStatus::Rejected,
139:                 'rejection_reason' => $reason,
140:             ]);
141: 
142:             return $customer->load(['customerGroup', 'documents']);
143:         });
144:     }
145: 
146:     /** إيقاف فوري: الحالة + السبب + حذف كل توكنات العميل في نفس اللحظة. */
147:     public function suspend(Customer $customer, string $reason): Customer
148:     {
149:         return DB::transaction(function () use ($customer, $reason): Customer {
150:             $customer = Customer::query()->lockForUpdate()->findOrFail($customer->id);
151:             if ($customer->status === CustomerStatus::Suspended) {
152:                 throw new BusinessException('هذا الحساب موقوف بالفعل.');
153:             }
154:             $customer->update([
155:                 'status' => CustomerStatus::Suspended,
156:                 'suspension_reason' => $reason,
157:             ]);
158:             $customer->tokens()->delete();
159: 
160:             return $customer->load('customerGroup');
161:         });
162:     }
