 32:     // ------------------------------------------------------------------ متاح
 33: 
 34:     /** إرفاق store_available بأي استعلام منتجات: مجموع متاح كل متغيراته في الفروع النشطة. */
 35:     public function withStoreAvailability(Builder $query): Builder
 36:     {
 37:         $sub = DB::table('stock_levels')
 38:             ->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
 39:             ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
 40:             ->where('branches.is_active', true)
 41:             ->where('product_variants.is_active', true)
 42:             ->whereNull('product_variants.deleted_at')
 43:             ->whereColumn('product_variants.product_id', 'products.id')
 44:             ->selectRaw('COALESCE(SUM(stock_levels.available), 0)');
 45: 
 46:         return $query->select('products.*')->selectSub($sub, 'store_available');
 47:     }
 48: 
 49:     /**
 50:      * خريطة متاح لمتغيرات بعينها في استعلام واحد مجمّع.
 51:      *
 52:      * @param  list<int>  $variantIds
 53:      * @return array<int, float>
 54:      */
 55:     public function availabilityMap(array $variantIds): array
 56:     {
 57:         if ($variantIds === []) {
 58:             return [];
 59:         }
 60: 
 61:         return StockLevel::query()
 62:             ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
 63:             ->where('branches.is_active', true)
 64:             ->whereIn('stock_levels.product_variant_id', $variantIds)
 65:             ->groupBy('stock_levels.product_variant_id')
 66:             ->selectRaw('stock_levels.product_variant_id, COALESCE(SUM(stock_levels.available), 0) as total')
 67:             ->pluck('total', 'product_variant_id')
 68:             ->map(fn ($v) => (float) $v)
 69:             ->all();
 70:     }
