 72:     // ------------------------------------------------------------------ أساس
 73: 
 74:     /** استعلام المنتجات المنشورة بعلاقات البطاقة والمتاح المجمّع. */
 75:     public function publishedQuery(): Builder
 76:     {
 77:         $query = Product::query()
 78:             ->where('status', ProductStatus::Published)
 79:             ->whereIn('sales_channel', [SalesChannel::Retail, SalesChannel::Both])
 80:             ->whereHas('category', fn ($q) => $q->where('is_active', true)
 81:                 ->whereDoesntHave('parent', fn ($parent) => $parent->where('is_active', false)
 82:                     ->orWhereHas('parent', fn ($ancestor) => $ancestor->where('is_active', false))))
 83:             ->where(fn ($q) => $q->whereNull('brand_id')->orWhereHas('brand', fn ($brand) => $brand->where('is_active', true)))
 84:             ->with([
 85:                 'brand', 'category', 'media',
 86:                 'variants' => fn ($q) => $this->pricing->withStorePrice($q->getQuery(), $this->customer())
 87:                     ->where('is_active', true)->orderBy('sort_order')->orderBy('id'),
 88:             ]);
 89: 
 90:         return $this->withStoreAvailability($query);
 91:     }
 92: 
 93:     // ------------------------------------------------------------------ فلاتر
 94: 
 95:     /**
 96:      * تطبيق فلاتر قائمة المنتجات (ProductFilterRequest) على الاستعلام.
 97:      *
 98:      * @param  array<string, mixed>  $filters
 99:      */
100:     public function applyFilters(Builder $query, array $filters): Builder
101:     {
102:         if (! empty($filters['category'])) {
103:             $category = $this->resolveCategory($filters['category']);
104:             if ($category !== null) {
105:                 $query->whereIn('products.category_id', [$category->id, ...$category->descendantIds()]);
106:             } else {
107:                 $query->whereRaw('1 = 0'); // قسم غير موجود = نتيجة فارغة لا خطأ
108:             }
109:         }
110: 
111:         if (! empty($filters['brand'])) {
112:             $values = (array) $filters['brand'];
113:             $numericIds = array_map('intval', array_filter($values, fn ($v) => ctype_digit((string) $v)));
114:             $brandIds = Brand::query()->where('is_active', true)
115:                 ->where(fn ($q) => $q->whereIn('id', $numericIds)->orWhereIn('slug', $values))
116:                 ->pluck('id')->all();
117:             $query->whereIn('products.brand_id', $brandIds ?: [0]);
118:         }
119: 
120:         if (! empty($filters['color'])) {
121:             $color = $filters['color'];
122:             $query->whereHas('variants', fn ($q) => $q->where('is_active', true)
123:                 ->where(fn ($inner) => $inner
124:                     ->whereRaw('LOWER(color_name_en) = LOWER(?)', [$color])
125:                     ->orWhere('color_name_ar', $color)));
126:         }
127: 
128:         if (isset($filters['price_min']) || isset($filters['price_max'])) {
129:             if (isset($filters['price_min'])) {
130:                 $query->where($this->minimumPriceQuery(), '>=', $filters['price_min']);
131:             }
132:             if (isset($filters['price_max'])) {
133:                 $query->where($this->minimumPriceQuery(), '<=', $filters['price_max']);
134:             }
135:         }
136: 
137:         if (! empty($filters['in_stock'])) {
138:             $query->whereExists(fn ($sub) => $sub
139:                 ->select(DB::raw(1))
140:                 ->from('stock_levels')
141:                 ->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
142:                 ->join('branches', 'branches.id', '=', 'stock_levels.branch_id')
143:                 ->where('branches.is_active', true)
144:                 ->where('product_variants.is_active', true)
145:                 ->whereNull('product_variants.deleted_at')
146:                 ->whereColumn('product_variants.product_id', 'products.id')
147:                 ->where('stock_levels.available', '>', 0));
148:         }
149: 
150:         return $this->applySort($query, $filters['sort'] ?? 'newest');
151:     }
152: 
153:     private function applySort(Builder $query, string $sort): Builder
154:     {
155:         if (in_array($sort, ['price_asc', 'price_desc'], true)) {
156:             $prices = $this->minimumPriceQuery();
157: 
158:             return $query->orderByRaw('('.$prices->toSql().') '.($sort === 'price_asc' ? 'ASC' : 'DESC').' NULLS LAST', $prices->getBindings())
159:                 ->orderBy('products.id');
160:         }
161: 
162:         return match ($sort) {
163:             'best_selling' => $query->orderByDesc('products.sales_count')->orderByDesc('products.id'),
164:             default => $query->orderByDesc('products.created_at')->orderByDesc('products.id'),
165:         };
166:     }
167: 
168:     private function resolveCategory(int|string $value): ?Category
169:     {
170:         return Category::query()
171:             ->where('is_active', true)
172:             ->when(is_numeric($value), fn ($q) => $q->where('id', (int) $value), fn ($q) => $q->where('slug', $value))
173:             ->first();
174:     }
175: 
176:     // ------------------------------------------------------------------ أسعار العرض
177: 
178:     /**
179:      * سعر عرض بطاقة المنتج: أرخص متغير نشط قابل للتسعير عبر PricingService
180:      * (متغير بلا سعر ولا قائمة يُتخطى بدل كسر القائمة كلها).
181:      *
182:      * @return array{price: float, base_price: float, compare_at: float|null, discount_percentage: int|null, variant_id: int}|null
183:      */
184:     public function displayPrice(Product $product, ?Customer $customer): ?array
185:     {
186:         $variants = $product->relationLoaded('variants')
187:             ? $product->variants
188:             : $product->variants()->where('is_active', true)->orderBy('sort_order')->get();
189: 
190:         $best = null;
191:         foreach ($variants as $variant) {
192:             try {
193:                 $resolved = $this->variantPrice($variant, $customer);
194:             } catch (BusinessException) {
195:                 continue;
196:             }
197: 
198:             $price = (float) $resolved['unit_price'];
199:             $compareAt = $variant->compare_at_price !== null ? (float) $variant->compare_at_price : null;
200:             $basis = max((float) $compareAt, (float) $resolved['base_price']);
201: 
202:             $display = [
203:                 'price' => $price,
204:                 'base_price' => (float) $resolved['base_price'],
205:                 'compare_at' => $basis > $price ? $basis : null,
206:                 'discount_percentage' => $basis > $price ? (int) round((1 - $price / $basis) * 100) : null,
207:                 'variant_id' => $variant->id,
208:             ];
209:             if ($best === null || $price < $best['price']) {
210:                 $best = $display;
211:             }
212:         }
213: 
214:         return $best;
215:     }
