217:     public function customer(): ?Customer
218:     {
219:         $user = auth('sanctum')->user();
220: 
221:         return $user instanceof Customer && $user->status === CustomerStatus::Approved ? $user : null;
222:     }
223: 
224:     public function variantPrice(ProductVariant $variant, ?Customer $customer): array
225:     {
226:         if (! array_key_exists('store_price', $variant->getAttributes())) {
227:             return $this->pricing->resolve($variant, $customer, 1);
228:         }
229:         if ($variant->store_price === null) {
230:             throw new BusinessException('الصنف غير مُسعَّر.');
231:         }
232: 
233:         return ['unit_price' => (float) $variant->store_price, 'base_price' => (float) $variant->base_price];
234:     }
