239:             ->where('is_active', true);
240: 
241:         return DB::query()->fromSub($variants, 'priced_variants')
242:             ->selectRaw('MIN(priced_variants.store_price)')
243:             ->whereColumn('priced_variants.product_id', 'products.id');
244:     }
