252:             ->where('is_active', true)
253:             ->where(fn ($q) => $q->whereNull('starts_at')->orWhere('starts_at', '<=', now()))
254:             ->where(fn ($q) => $q->whereNull('ends_at')->orWhere('ends_at', '>=', now()))
255:             ->orderBy('sort_order')->orderBy('id')
256:             ->pluck('id')->all();
257: 
258:         $latest = $this->publishedQuery()->reorder()->orderByDesc('products.created_at')->orderByDesc('products.id')->limit(12)->pluck('products.id')->all();
259:         $best = $this->publishedQuery()->reorder()->orderByDesc('products.sales_count')->orderByDesc('products.id')->limit(12)->pluck('products.id')->all();
260: 
261:         $discounted = $this->publishedQuery()->reorder()
262:             ->where(fn ($q) => $q
263:                 ->whereHas('variants', fn ($v) => $v->where('is_active', true)
264:                     ->whereNotNull('retail_price')
265:                     ->whereNotNull('compare_at_price')
266:                     ->whereColumn('compare_at_price', '>', 'base_price'))
267:                 ->orWhereHas('variants', fn ($v) => $v->where('is_active', true)
268:                     ->whereExists(fn ($sub) => $sub->select(DB::raw(1))
269:                         ->from('price_list_items')
270:                         ->join('price_lists', 'price_lists.id', '=', 'price_list_items.price_list_id')
271:                         ->whereColumn('price_list_items.product_variant_id', 'product_variants.id')
272:                         ->where('price_lists.is_active', true)
273:                         ->where('price_lists.type', 'retail')
274:                         ->whereNull('price_lists.branch_id')
275:                         ->where('price_list_items.min_qty', '<=', 1)
276:                         ->where(fn ($w) => $w->whereNull('price_lists.starts_at')->orWhere('price_lists.starts_at', '<=', now()))
277:                         ->where(fn ($w) => $w->whereNull('price_lists.ends_at')->orWhere('price_lists.ends_at', '>=', now()))
278:                         ->where(fn ($w) => $w->whereNull('price_list_items.starts_at')->orWhere('price_list_items.starts_at', '<=', now()))
279:                         ->where(fn ($w) => $w->whereNull('price_list_items.ends_at')->orWhere('price_list_items.ends_at', '>=', now()))
280:                         ->whereColumn('price_list_items.price', '<', 'product_variants.base_price'))))
281:             ->orderByDesc('products.sales_count')->orderByDesc('products.id')
