 22: class WholesaleRegistrationService
 23: {
 24:     public function __construct(private readonly CustomerAuthService $auth) {}
 25: 
 26:     /**
 27:      * @param  list<UploadedFile>  $files
 28:      * @param  list<string|null>  $documentTypes  أنواع موازية للملفات (افتراضي other)
 29:      * @return array{customer: Customer, token: string}
 30:      */
 31:     public function register(array $data, array $files, array $documentTypes = []): array
 32:     {
 33:         $storedPaths = [];
 34:         $staged = [];
 35:         $stagingDirectory = 'customer_documents/pending/'.Str::uuid();
 36: 
 37:         try {
 38:             foreach ($files as $i => $file) {
 39:                 $filename = Str::uuid().'.'.($file->extension() ?: 'bin');
 40:                 $path = Storage::disk('local')->putFileAs($stagingDirectory, $file, $filename);
 41:                 if ($path === false) {
 42:                     throw new \RuntimeException('تعذر حفظ مستند العميل.');
 43:                 }
 44:                 $storedPaths[] = $path;
 45:                 $staged[] = [
 46:                     'filename' => $filename, 'path' => $path,
 47:                     'document_type' => $documentTypes[$i] ?? CustomerDocumentType::Other->value,
 48:                     'original_name' => CustomerDocument::safeName($file->getClientOriginalName()),
 49:                     'mime_type' => $file->getMimeType() ?? 'application/octet-stream',
 50:                 ];
 51:             }
 52: 
 53:             $registration = DB::transaction(function () use ($data, $staged, &$storedPaths): array {
 54:                 $customer = Customer::query()->create([
 55:                     'name' => $data['name'],
 56:                     'email' => $data['email'] ?? null,
 57:                     'phone' => $data['phone'],
 58:                     'password' => $data['password'],
 59:                     'type' => CustomerType::Wholesale,
 60:                     'status' => CustomerStatus::Pending,
 61:                     'company_name' => $data['company_name'],
 62:                     'tax_number' => $data['tax_number'],
 63:                     'commercial_register' => $data['commercial_register'],
 64:                 ]);
 65: 
 66:                 foreach ($staged as $document) {
 67:                     // تخزين خاص: وثائق الشركات لا تخرج بروابط عامة أبدًا،
 68:                     // والتنزيل لاحقًا عبر نهاية الأدمن المحمية فقط.
 69:                     $path = "customer_documents/{$customer->id}/".$document['filename'];
 70:                     if (! Storage::disk('local')->move($document['path'], $path)) {
 71:                         throw new \RuntimeException('تعذر حفظ مستند العميل.');
 72:                     }
 73:                     $storedPaths[] = $path;
 74: 
 75:                     $customer->documents()->create([
 76:                         'document_type' => $document['document_type'],
 77:                         'file_path' => $path,
 78:                         'original_name' => $document['original_name'],
 79:                         'mime_type' => $document['mime_type'],
 80:                         'status' => CustomerDocumentStatus::Pending,
 81:                     ]);
 82:                 }
 83: 
 84:                 return [
 85:                     'customer' => $customer->load('documents'),
 86:                     'token' => $this->auth->issueToken($customer, 'wholesale-token'),
 87:                 ];
 88:             });
 89:         } catch (\Throwable $e) {
 90:             // فشل قاعدة البيانات بعد رفع ملفات: نظّفها حتى لا تبقى يتيمة
 91:             foreach ($storedPaths as $path) {
 92:                 Storage::disk('local')->delete($path);
 93:             }
 94:             if ($storedPaths !== []) {
 95:                 Storage::disk('local')->deleteDirectory($stagingDirectory);
 96:             }
 97: 
 98:             throw $e;
 99:         }
100: 
101:         Storage::disk('local')->deleteDirectory($stagingDirectory);
102: 
103:         return $registration;
104:     }
