34:             'color_hex' => $color['hex'],
35:             'size' => fake()->randomElement(['S', 'M', 'L', null]),
36:             'capacity' => null,
37:             'cost_price' => $cost,
38:             'retail_price' => round($cost * 1.6, 2),
