 78:     private function ean13CheckDigitIsValid(string $barcode): bool
 79:     {
 80:         $sum = 0;
 81:         foreach (str_split(substr($barcode, 0, 12)) as $i => $digit) {
 82:             $sum += (int) $digit * ($i % 2 === 0 ? 1 : 3);
 83:         }
 84: 
 85:         return ((10 - ($sum % 10)) % 10) === (int) $barcode[12];
 86:     }
