 44:         $this->withToken($token)->postJson('/api/v1/store/auth/logout')->assertOk();
 45:         // وبعد الخروج يموت التوكن نفسه
 46:         Auth::forgetGuards();
 47:         $this->withToken($token)->postJson('/api/v1/store/auth/logout')->assertUnauthorized();
