 47:     public function test_home_aggregates_sections_and_caches_ids(): void
 48:     {
 49:         Banner::factory()->create(['title' => 'ساري', 'sort_order' => 1]);
 50:         Banner::factory()->create(['title' => 'مستقبلي', 'starts_at' => now()->addDay()]);
 51:         Banner::factory()->create(['title' => 'منتهي', 'ends_at' => now()->subDay()]);
 52:         Banner::factory()->create(['title' => 'معطل', 'is_active' => false]);
 53:         $old = $this->product(['sales_count' => 50]);
 54:         $new = $this->product();
 55:         $discounted = $this->product();
 56:         $discounted->variants()->first()->update(['compare_at_price' => 1500]);
 57:         Product::factory()->create(['status' => ProductStatus::Draft]);
 58: 
 59:         $response = $this->getJson('/api/v1/store/home')->assertOk();
 60:         $this->assertSame(['ساري'], collect($response->json('data.banners'))->pluck('title')->all());
 61:         $this->assertSame($discounted->id, $response->json('data.latest_products.0.id')); // الأحدث إنشاءً
 62:         $this->assertSame($old->id, $response->json('data.best_sellers.0.id'));
 63:         $this->assertContains($discounted->id, collect($response->json('data.discounted_products'))->pluck('id')->all());
 64:         $this->assertSame(3, collect($response->json('data.latest_products'))->count()); // المسودة مستبعدة
 65: 
 66:         // الكاش: منتج أحدث يُنشأ بعد أول طلب لا يظهر حتى انتهاء الخمس دقائق
 67:         $this->product();
 68:         $again = $this->getJson('/api/v1/store/home')->assertOk();
 69:         $this->assertSame(3, collect($again->json('data.latest_products'))->count());
 70:         Cache::forget('store_home_data');
 71:         $fresh = $this->getJson('/api/v1/store/home')->assertOk();
 72:         $this->assertSame(4, collect($fresh->json('data.latest_products'))->count());
 73:     }
