100:     public function test_products_filters_and_sorts(): void
101:     {
102:         $catA = Category::factory()->create();
103:         $subA = Category::factory()->create(['parent_id' => $catA->id]);
104:         $brandX = Brand::factory()->create();
105:         $brandY = Brand::factory()->create();
106: 
107:         $p1 = $this->product(['category_id' => $subA->id, 'brand_id' => $brandX->id], ['color_name_en' => 'Black', 'retail_price' => 500]);
108:         $p2 = $this->product(['category_id' => $catA->id, 'brand_id' => $brandY->id], ['color_name_en' => 'Red', 'retail_price' => 1500]);
109:         $p3 = $this->product(['brand_id' => $brandY->id], ['retail_price' => 900]);
110:         $this->stock($p1->variants->first(), 3);
111:         Product::factory()->create(['status' => ProductStatus::Draft, 'category_id' => $subA->id]);
112: 
113:         // القسم بالـ slug يشمل الفرعي
114:         $byCat = $this->getJson("/api/v1/store/products?category={$catA->slug}")->assertOk();
115:         $this->assertEqualsCanonicalizing([$p1->id, $p2->id], collect($byCat->json('data'))->pluck('id')->all());
116: 
117:         // علامات متعددة + لون + مدى سعر
118:         $filtered = $this->getJson('/api/v1/store/products?brand[]='.$brandX->slug.'&brand[]='.$brandY->id.'&color=black&price_min=100&price_max=1000')->assertOk();
119:         $this->assertSame([$p1->id], collect($filtered->json('data'))->pluck('id')->all());
120: 
121:         // المتوفر فقط
122:         $inStock = $this->getJson('/api/v1/store/products?in_stock=1')->assertOk();
123:         $this->assertSame([$p1->id], collect($inStock->json('data'))->pluck('id')->all());
124:         $card = collect($inStock->json('data'))->first();
125:         $this->assertTrue($card['in_stock']);
126:         $this->assertSame(3.0, (float) $card['store_available']);
127: 
128:         // الفرز بالسعر
129:         $asc = $this->getJson('/api/v1/store/products?sort=price_asc')->assertOk();
130:         $this->assertSame([$p1->id, $p3->id, $p2->id], collect($asc->json('data'))->pluck('id')->all());
131: 
132:         // مخزون في فرع معطّل لا يُحتسب
133:         $p4 = $this->product();
134:         $this->stock($p4->variants->first(), 9, branchActive: false);
135:         $inStock2 = $this->getJson('/api/v1/store/products?in_stock=1')->assertOk();
136:         $this->assertSame([$p1->id], collect($inStock2->json('data'))->pluck('id')->all());
137:     }
