13:     protected function idempotencyKey(Request $request): ?string
14:     {
15:         $key = $request->header('Idempotency-Key');
16:         if ($key === null) {
17:             return null;
18:         }
19: 
20:         $key = trim($key);
21:         if ($key === '' || strlen($key) > 128) {
22:             throw new BusinessException('قيمة Idempotency-Key غير صالحة (1 إلى 128 حرفًا).');
23:         }
24: 
25:         return $key;
26:     }
