 5: namespace App\Http\Requests\Admin\Concerns;
 6: 
 7: use App\Models\ProductVariant;
 8: use Illuminate\Validation\Validator;
 9: 
10: /**
11:  * تحقق وجود المتغيرات باستعلام واحد مجمّع (whereIn) بدل Rule::exists لكل عنصر —
12:  * جرد/تحويل من 500 صنف كان ينفذ 500 استعلام قبل بدء العمل أصلًا (M11).
13:  * النشاط (is_active) لا يُفحص هنا: عمليات الإخراج مسموحة على المعطّل (M5)،
14:  * والإدخال يُحظر في الخدمة نفسها.
15:  */
16: trait BulkVariantExists
17: {
18:     protected function addBulkVariantExistsCheck(Validator $validator): void
19:     {
20:         $validator->after(function (Validator $v): void {
21:             $items = $this->input('items', []);
22:             if (! is_array($items) || $items === []) {
23:                 return;
24:             }
25: 
26:             $ids = collect($items)
27:                 ->pluck('product_variant_id')
28:                 ->filter(fn ($id) => is_numeric($id))
29:                 ->map(fn ($id) => (int) $id)
30:                 ->unique()
31:                 ->values();
32: 
33:             if ($ids->isEmpty()) {
34:                 return;
35:             }
36: 
37:             // withTrashed: متغير محذوف ناعمًا وله رصيد لا يجب أن يُحبس رصيده —
38:             // عمليات الإخراج (تسوية/جرد/تحويل) تظل ممكنة عليه لتصفيته (M-9)،
39:             // والإدخال عليه محظور في InventoryService لأنه يعامل كمعطّل.
40:             $found = ProductVariant::query()->withTrashed()->whereIn('id', $ids)->pluck('id')->map(fn ($id) => (int) $id)->all();
41:             $missing = $ids->diff($found);
42: 
43:             if ($missing->isEmpty()) {
44:                 return;
45:             }
46: 
47:             foreach ($items as $i => $item) {
48:                 if (isset($item['product_variant_id']) && $missing->contains((int) $item['product_variant_id'])) {
49:                     $v->errors()->add("items.{$i}.product_variant_id", 'المتغير المحدد غير موجود.');
50:                 }
51:             }
52:         });
53:     }
54: } 1: <?php
