10: 
11: // مسارات الميديا بالـ uuid بدل الـ id المتسلسل، فصور المسودات مبتتخمنش بترقيم بسيط
12: class UuidPathGenerator implements PathGenerator
13: {
14:     public function getPath(Media $media): string
15:     {
16:         if (! $media->uuid || $media->getCustomProperty('path_layout') === 'id') {
17:             return $media->id.'/';
18:         }
19: 
20:         if (! $media->hasCustomProperty('path_layout')) {
21:             // Cache on this model instance; the backfill command persists it for future requests.
22:             $media->setCustomProperty('path_layout', Storage::disk($media->disk)->exists($media->id.'/'.$media->file_name) ? 'id' : 'uuid');
23:             if ($media->getCustomProperty('path_layout') === 'id') {
24:                 return $media->id.'/';
25:             }
26:         }
27: 
28:         return $media->uuid.'/';
29:     }
30: 
31:     public function getPathForConversions(Media $media): string
32:     {
33:         return $this->getPath($media).'conversions/';
34:     }
35: 
36:     public function getPathForResponsiveImages(Media $media): string
37:     {
38:         return $this->getPath($media).'responsive-images/';
39:     }
