 7: use App\Enums\StaffRole;
 8: use App\Models\User;
 9: use Illuminate\Auth\Access\AuthorizationException;
10: 
11: /**
12:  * نطاق الفروع للموظفين — Fail-Closed:
13:  * الوصول لكل الفروع امتياز صريح (Super Admin أو صلاحية inventory.all_branches)،
14:  * والموظف المرتبط بفرع محصور فيه، ومن لا فرع له ولا امتياز يُرفض بدل أن يرى كل شيء.
15:  */
16: class BranchAccess
17: {
18:     /** @var array<int, User> ذاكرة لكل طلب حتى لا يُعاد تحميل المستخدم مع كل فحص. */
19:     private array $usersById = [];
20: 
21:     public function restrictedBranch(?User $user): ?int
22:     {
23:         if ($user === null) {
24:             throw new AuthorizationException;
25:         }
26: 
27:         if ($user->hasRole(StaffRole::SuperAdmin->value, 'staff') || $user->can('inventory.all_branches')) {
28:             return null;
29:         }
30: 
31:         if ($user->branch_id !== null) {
32:             return (int) $user->branch_id;
33:         }
34: 
35:         throw new AuthorizationException('حسابك غير مرتبط بأي فرع ولا تملك صلاحية الوصول لكل الفروع (inventory.all_branches).');
36:     }
37: 
38:     public function assertBranch(int $userId, int ...$branchIds): void
39:     {
40:         $branchId = $this->restrictedBranch($this->usersById[$userId] ??= User::findOrFail($userId));
41:         if ($branchId !== null && ! in_array($branchId, $branchIds, true)) {
42:             throw new AuthorizationException('لا تملك صلاحية الوصول إلى هذا الفرع.');
43:         }
44:     }
45: 
46:     public function assertCentralAccess(?User $user): void
47:     {
48:         if ($this->restrictedBranch($user) !== null) {
49:             throw new AuthorizationException('تعديل مجموعات العملاء والأسعار العامة يتطلب صلاحية الوصول لكل الفروع.');
50:         }
51:     }
52: }  1: <?php
