  5: namespace App\Services;
  6: 
  7: use App\Enums\CustomerStatus;
  8: use App\Enums\CustomerType;
  9: use App\Enums\PriceListType;
 10: use App\Exceptions\BusinessException;
 11: use App\Models\Customer;
 12: use App\Models\PriceListItem;
 13: use App\Models\ProductVariant;
 14: use Carbon\Carbon;
 15: use Illuminate\Database\Eloquent\Builder;
 16: 
 17: /**
 18:  * محرك التسعير المركزي — يُستدعى من المتجر والجملة والـ POS ولوحة الإدارة.
 19:  *
 20:  * شجرة الأولويات:
 21:  * 1. سعر خاص بالعميل (customer_specific)
 22:  * 2. سعر مجموعة العميل (customer_group)
 23:  * 3. قائمة النوع (wholesale/distributor للمعتمدين فقط، وإلا retail)؛ وقناة
 24:  *    جملة/موزع بلا عنصر مطابق ترجع لقوائم retail النشطة قبل السعر الأساسي.
 25:  * 4. السعر الأساسي للمتغير (base_price، المتوافق مع retail_price من المرحلة 2).
 26:  *
 27:  * خصم مجموعة العميل (discount_percentage) لا يصنع مستوى مستقلًا: يُطبق فوق ناتج
 28:  * المستويين 3/4 (سعر القناة)، ولا يُخصم من سعر خاص بالعميل أو سعر قائمة المجموعة.
 29:  * متغير بلا retail_price ولا قائمة مطابقة = غير مُسعَّر، ويرمي BusinessException.
 30:  *
 31:  * داخل كل مستوى: القائمة المخصصة للفرع أولًا، ثم أعلى شريحة كمية محققة،
 32:  * ثم أولوية القائمة، ثم السعر الأقل.
 33:  */
 34: class PricingService
 35: {
 36:     /** Resolve storefront prices in SQL using the same owner, tier and priority rules as resolve(). */
 37:     public function withStorePrice(Builder $variants, ?Customer $customer): Builder
 38:     {
 39:         $eligible = $customer !== null && $customer->status === CustomerStatus::Approved;
 40:         $channel = $this->channelFor($customer);
 41:         $group = $eligible ? $customer->customerGroup : null;
 42:         $group = $group?->is_active ? $group : null;
 43:         $factor = $group !== null ? 1 - (float) $group->discount_percentage / 100 : 1;
 44:         $items = $this->eligibleItems(null, 1, null, Carbon::now())
 45:             ->where(function ($q) use ($eligible, $customer, $group, $channel): void {
 46:                 $q->whereIn('price_lists.type', array_unique([$channel->value, PriceListType::Retail->value]));
 47:                 if ($eligible) {
 48:                     $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerSpecific)
 49:                         ->where('price_lists.customer_id', $customer->id));
 50:                 }
 51:                 if ($group !== null) {
 52:                     $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerGroup)
 53:                         ->where('price_lists.customer_group_id', $group->id));
 54:                 }
 55:             })
 56:             ->select([])
 57:             ->selectRaw("price_list_items.price * CASE WHEN price_lists.type IN ('customer_specific', 'customer_group') THEN 1::numeric ELSE ?::numeric END", [$factor])
 58:             ->orderByRaw("CASE WHEN price_lists.type = 'customer_specific' THEN 0 WHEN price_lists.type = 'customer_group' THEN 1 WHEN price_lists.type = ? THEN 2 ELSE 3 END", [$channel->value]);
 59:         $items = $this->ordered($items)->limit(1);
 60: 
 61:         return $variants->select('product_variants.*')
 62:             ->selectRaw('ROUND(COALESCE(('.$items->toSql().'), product_variants.retail_price * ?)::numeric, 2) AS store_price', [...$items->getBindings(), $factor]);
 63:     }
 64: 
 65:     /**
 66:      * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
 67:      */
 68:     public function resolve(
 69:         ProductVariant $variant,
 70:         ?Customer $customer = null,
 71:         float $qty = 1,
 72:         ?int $branchId = null,
 73:     ): array {
 74:         if (! is_finite($qty) || $qty <= 0) {
 75:             throw new BusinessException('كمية التسعير يجب أن تكون موجبة.');
 76:         }
 77:         $now = Carbon::now();
 78: 
 79:         $baseQuery = $this->eligibleItems($variant, $qty, $branchId, $now);
 80:         $channel = $this->channelFor($customer);
 81:         $eligibleCustomer = $customer !== null && $customer->status === CustomerStatus::Approved;
 82: 
 83:         // الأولوية 1: سعر خاص بالعميل
 84:         if ($eligibleCustomer) {
 85:             $item = $this->ordered((clone $baseQuery)
 86:                 ->where('price_lists.type', PriceListType::CustomerSpecific)
 87:                 ->where('price_lists.customer_id', $customer->id)
 88:             )->first();
 89: 
 90:             if ($item !== null) {
 91:                 return $this->formatResponse((float) $item->price, PriceListType::CustomerSpecific->value, (int) $item->price_list_id, $variant, $channel);
 92:             }
 93:         }
 94: 
 95:         // الأولوية 2: سعر مجموعة العميل
 96:         $group = $eligibleCustomer ? $customer->customerGroup()->where('is_active', true)->first() : null;
 97:         if ($group !== null) {
 98:             $item = $this->ordered((clone $baseQuery)
 99:                 ->where('price_lists.type', PriceListType::CustomerGroup)
100:                 ->where('price_lists.customer_group_id', $group->id)
101:             )->first();
102: 
103:             if ($item !== null) {
104:                 return $this->formatResponse((float) $item->price, PriceListType::CustomerGroup->value, (int) $item->price_list_id, $variant, $channel);
105:             }
106:         }
107: 
108:         // الأولوية 3: قائمة نوع العميل (أو القطاعي افتراضيًا)
109:         $item = $this->ordered((clone $baseQuery)
110:             ->where('price_lists.type', $channel)
111:         )->first();
112: 
113:         // قناة جملة/موزع بلا عنصر في قائمتها ترجع لقوائم القطاعي النشطة قبل
114:         // السعر الأساسي — وإلا دفع عميل الجملة أكثر من عميل التجزئة (M-1).
115:         if ($item === null && $channel !== PriceListType::Retail) {
116:             $item = $this->ordered((clone $baseQuery)
117:                 ->where('price_lists.type', PriceListType::Retail)
118:             )->first();
119: 
120:             if ($item !== null) {
121:                 $channel = PriceListType::Retail;
122:             }
123:         }
124: 
125:         if ($item !== null) {
126:             $channelPrice = (float) $item->price;
127:             $channelListId = (int) $item->price_list_id;
128:             $channelSource = $channel->value;
129:         } elseif ($variant->retail_price === null) {
130:             // الأولوية 4 مستحيلة: لا قائمة مطابقة ولا سعر قطاعي — الصنف غير مُسعَّر
131:             // ولا يجوز أن يخرج بسعر صفر ليُباع مجانًا.
132:             throw new BusinessException('الصنف غير مُسعَّر: لا توجد قائمة أسعار مطابقة ولا سعر قطاعي للمتغير.');
133:         } else {
134:             // الأولوية 4: السعر الأساسي الموحد؛ أسعار الجملة والموزعين تأتي من القوائم.
135:             $channelPrice = $this->basePrice($variant, $channel);
136:             $channelListId = null;
137:             $channelSource = 'base_price';
138:         }
139: 
140:         // خصم مجموعة العميل يُطبق "فوق" سعر القناة المحسوب (قائمة القناة أو الأساسي)،
141:         // ولا يتجاوزه أبدًا — فلا يخسر العميل سعر جملة/موزع أفضل بسبب خصم مجموعته.
142:         if ($group !== null && (float) $group->discount_percentage > 0) {
143:             return $this->formatResponse(
144:                 $channelPrice * (1 - (float) $group->discount_percentage / 100),
145:                 'customer_group_discount',
146:                 $channelListId,
147:                 $variant,
148:                 $channel,
149:             );
150:         }
151: 
152:         return $this->formatResponse($channelPrice, $channelSource, $channelListId, $variant, $channel);
153:     }
154: 
155:     /** قناة التسعير: الجملة/الموزع للحسابات المعتمدة فقط، وغير ذلك قطاعي. */
156:     private function channelFor(?Customer $customer): PriceListType
157:     {
158:         if ($customer !== null
159:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true)
160:             && $customer->status === CustomerStatus::Approved) {
161:             return PriceListType::from($customer->type->value);
162:         }
163: 
164:         return PriceListType::Retail;
165:     }
166: 
167:     private function basePrice(ProductVariant $variant, PriceListType $channel): float
168:     {
169:         return (float) $variant->base_price;
170:     }
171: 
172:     /** كل عناصر التسعير السارية لهذا المتغير والكمية والفرع والوقت. */
173:     private function eligibleItems(?ProductVariant $variant, float $qty, ?int $branchId, Carbon $now): Builder
174:     {
175:         return PriceListItem::query()
176:             ->select('price_list_items.*')
177:             ->join('price_lists', 'price_lists.id', '=', 'price_list_items.price_list_id')
178:             ->where('price_lists.is_active', true)
179:             ->when($variant !== null,
180:                 fn ($q) => $q->where('price_list_items.product_variant_id', $variant->id),
181:                 fn ($q) => $q->whereColumn('price_list_items.product_variant_id', 'product_variants.id'))
182:             ->where('price_list_items.min_qty', '<=', $qty)
183:             ->where(fn ($q) => $q->whereNull('price_lists.starts_at')->orWhere('price_lists.starts_at', '<=', $now))
184:             ->where(fn ($q) => $q->whereNull('price_lists.ends_at')->orWhere('price_lists.ends_at', '>=', $now))
185:             ->where(fn ($q) => $q->whereNull('price_list_items.starts_at')->orWhere('price_list_items.starts_at', '<=', $now))
186:             ->where(fn ($q) => $q->whereNull('price_list_items.ends_at')->orWhere('price_list_items.ends_at', '>=', $now))
187:             ->where(function ($q) use ($branchId): void {
188:                 $q->whereNull('price_lists.branch_id');
189:                 if ($branchId !== null) {
190:                     $q->orWhere('price_lists.branch_id', $branchId);
191:                 }
192:             });
193:     }
194: 
195:     /** ترتيب داخل المستوى الواحد: فرع مخصص أولًا، أعلى شريحة، أعلى أولوية، أقل سعر. */
196:     private function ordered(Builder $query): Builder
197:     {
198:         return $query
199:             ->orderByRaw('price_lists.branch_id IS NULL ASC')
200:             ->orderByDesc('price_list_items.min_qty')
201:             ->orderByDesc('price_lists.priority')
202:             ->orderBy('price_list_items.price');
203:     }
204: 
205:     /**
206:      * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
207:      */
208:     private function formatResponse(float $unitPrice, string $source, ?int $priceListId, ProductVariant $variant, PriceListType $channel): array
209:     {
210:         return [
211:             'unit_price' => round($unitPrice, 2),
212:             'base_price' => round($this->basePrice($variant, $channel), 2),
213:             'source' => $source,
214:             'price_list_id' => $priceListId,
215:         ];
216:     }
