 5: namespace App\Services;
 6: 
 7: use Illuminate\Support\Str;
 8: 
 9: class SlugService
10: {
11:     public static function make(string $modelClass, string $source, ?int $ignoreId = null): string
12:     {
13:         $base = Str::slug($source) ?: strtolower(Str::random(8));
14:         // قص القاعدة لـ 240 حرف عشان اللاحقة الرقمية متعديش عمود varchar(255) وترجع 500
15:         $base = rtrim(Str::substr($base, 0, 240), '-');
16: 
17:         // استعلام واحد لكل اللاحقات، ثم اختيار أول لاحقة متاحة في الذاكرة.
18:         $like = strtr($base, ['\\' => '\\\\', '%' => '\\%', '_' => '\\_']).'-%';
19:         $query = $modelClass::withTrashed();
20:         $existing = $query
21:             ->when($query->getModel()->getConnection()->getDriverName() === 'pgsql',
22:                 fn ($q) => $q->whereRaw('slug ~* ?', ['^'.preg_quote($base).'(-[0-9]+)?$']),
23:                 fn ($q) => $q->where(fn ($where) => $where->whereLike('slug', $base)->orWhereLike('slug', $like)))
24:             ->when($ignoreId, fn ($q) => $q->where('id', '!=', $ignoreId))
25:             ->pluck('slug')->map(fn ($slug) => strtolower($slug));
26: 
27:         if (! $existing->contains($base)) {
28:             return $base;
29:         }
30: 
31:         $taken = array_fill_keys($existing->all(), true);
32:         $suffix = 2;
33:         while (isset($taken[$base.'-'.$suffix])) {
34:             $suffix++;
35:         }
36: 
37:         return $base.'-'.$suffix;
38:     }
39: } 1: <?php
