  5: namespace App\Services\Catalog;
  6: 
  7: use App\Exceptions\BusinessException;
  8: use App\Models\Category;
  9: use App\Services\SlugService;
 10: use Illuminate\Http\UploadedFile;
 11: use Illuminate\Support\Collection;
 12: use Illuminate\Support\Facades\DB;
 13: 
 14: class CategoryService
 15: {
 16:     public function create(array $data, ?UploadedFile $image): Category
 17:     {
 18:         $category = DB::transaction(function () use ($data, $image) {
 19:             $this->lockTree();
 20: 
 21:             unset($data['image']);
 22:             $data = array_filter($data, fn ($value) => $value !== null);
 23: 
 24:             if (empty($data['slug'])) {
 25:                 $data['slug'] = SlugService::make(Category::class, $data['name_en']);
 26:             }
 27: 
 28:             if (! empty($data['parent_id'])) {
 29:                 $parent = Category::findOrFail($data['parent_id']);
 30:                 if ($parent->depth() >= 3) {
 31:                     throw new BusinessException('أقصى عمق للأقسام 3 مستويات');
 32:                 }
 33:             }
 34: 
 35:             $category = Category::create($data);
 36:             if ($image) {
 37:                 $category->addMedia($image)->toMediaCollection('image');
 38:             }
 39: 
 40:             return $category;
 41:         });
 42: 
 43:         return $category;
 44:     }
 45: 
 46:     public function update(Category $category, array $data, ?UploadedFile $image): Category
 47:     {
 48:         $removeImage = (bool) ($data['remove_image'] ?? false);
 49:         unset($data['image'], $data['remove_image']);
 50:         if (isset($data['parent_id'])) {
 51:             $data['parent_id'] = (int) $data['parent_id'];
 52:         }
 53: 
 54:         foreach (['sort_order', 'is_active'] as $field) {
 55:             if (array_key_exists($field, $data) && $data[$field] === null) {
 56:                 unset($data[$field]);
 57:             }
 58:         }
 59:         $apply = function (bool $exclusive) use ($category, $data, $image, $removeImage): ?Category {
 60:             return DB::transaction(function () use ($category, $data, $image, $removeImage, $exclusive) {
 61:                 CatalogLock::tree(shared: ! $exclusive);
 62:                 $category = Category::whereKey($category->id)->lockForUpdate()->firstOrFail();
 63:                 $parentChanged = array_key_exists('parent_id', $data) && $data['parent_id'] !== $category->parent_id;
 64:                 $activeChanged = isset($data['is_active']) && (bool) $data['is_active'] !== $category->is_active;
 65:                 if (($parentChanged || $activeChanged) && ! $exclusive) {
 66:                     return null;
 67:                 }
 68:                 if ($parentChanged || $activeChanged) {
 69:                     $nodes = CategoryHierarchy::snapshot();
 70:                     $nodes[$category->id] = array_replace($nodes[$category->id], array_intersect_key($data, array_flip(['parent_id', 'is_active'])));
 71:                     CategoryHierarchy::assertValid($nodes);
 72:                     CategoryHierarchy::assertPublishedPathsActive($nodes);
 73:                 }
 74:                 if (array_key_exists('slug', $data) && empty($data['slug'])) {
 75:                     $data['slug'] = SlugService::make(Category::class, $data['name_en'] ?? $category->name_en, $category->id);
 76:                 }
 77: 
 78:                 foreach (['sort_order', 'is_active'] as $field) {
 79:                     if (array_key_exists($field, $data) && $data[$field] === null) {
 80:                         unset($data[$field]);
 81:                     }
 82:                 }
 83: 
 84:                 $category->update($data);
 85: 
 86:                 if ($removeImage) {
 87:                     $category->clearMediaCollection('image');
 88:                 }
 89: 
 90:                 if ($image) {
 91:                     $category->addMedia($image)->toMediaCollection('image');
 92:                 }
 93: 
 94:                 return $category;
 95:             });
 96:         };
 97: 
 98:         return $apply(false) ?? $apply(true);
 99:     }
100: 
101:     public function delete(Category $category): void
102:     {
103:         DB::transaction(function () use ($category): void {
104:             $this->lockTree();
105:             $locked = Category::whereKey($category->id)->lockForUpdate()->firstOrFail();
106: 
107:             if ($locked->children()->withTrashed()->exists()) {
108:                 throw new BusinessException('لا يمكن حذف قسم يحتوي على أقسام فرعية');
109:             }
110: 
111:             if ($locked->products()->withTrashed()->exists()) {
112:                 throw new BusinessException('لا يمكن حذف قسم مرتبط بمنتجات');
113:             }
114: 
115:             $locked->delete();
116:         });
117:     }
118: 
119:     public function reorder(array $items): void
120:     {
121:         // Retry with an exclusive tree lock only if the fresh snapshot contains a move.
122:         // Never upgrade a shared advisory lock while retaining it.
123:         $apply = function (bool $exclusive) use ($items): bool {
124:             return DB::transaction(function () use ($items, $exclusive): bool {
125:                 CatalogLock::tree(shared: ! $exclusive);
126:                 $categories = Category::query()->get()->keyBy('id');
127:                 $nodes = $categories->toArray();
128:                 $moved = false;
129:                 foreach ($items as $item) {
130:                     if (! array_key_exists('parent_id', $item)) {
131:                         throw new BusinessException('يجب إرسال parent_id لكل عنصر في الترتيب');
132:                     }
133:                     $category = $categories->get($item['id']);
134:                     if (! $category) {
135:                         throw new BusinessException('القسم غير موجود', ['items' => ['أحد الأقسام لم يعد متاحًا']]);
136:                     }
137:                     $parentId = $item['parent_id'] === null ? null : (int) $item['parent_id'];
138:                     $moved = $moved || $parentId !== $category->parent_id;
139:                     $nodes[$category->id]['parent_id'] = $parentId;
140:                 }
141:                 if ($moved && ! $exclusive) {
142:                     return false;
143:                 }
144:                 if ($moved) {
145:                     CategoryHierarchy::assertValid($nodes);
146:                     CategoryHierarchy::assertPublishedPathsActive($nodes);
147:                 }
148:                 foreach ($items as $item) {
149:                     $categories->get($item['id'])->update(['parent_id' => $nodes[$item['id']]['parent_id'], 'sort_order' => $item['sort_order']]);
150:                 }
151: 
152:                 return true;
153:             });
154:         };
155:         if (! $apply(false)) {
156:             $apply(true);
157:         }
158:     }
159: 
160:     public function tree(bool $onlyActive = false): Collection
161:     {
162:         $all = Category::query()->with('media')->withCount('products')
163:             ->when($onlyActive, fn ($q) => $q->where('is_active', true))
164:             ->orderBy('sort_order')->get();
165:         $grouped = $all->groupBy('parent_id');
166:         $build = function ($parentId) use (&$build, $grouped) {
167:             return ($grouped[$parentId ?? ''] ?? collect())->map(function ($cat) use ($build) {
168:                 $cat->setRelation('children', $build($cat->id));
169: 
170:                 return $cat;
171:             })->values();
172:         };
173: 
174:         return $build(null);
175:     }
176: 
177:     public function assertValidParent(Category $category, ?int $parentId): void
178:     {
179:         $nodes = CategoryHierarchy::snapshot();
180:         $nodes[$category->id]['parent_id'] = $parentId;
181:         CategoryHierarchy::assertValid($nodes);
182:         CategoryHierarchy::assertPublishedPathsActive($nodes);
183:     }
184: 
185:     private function lockTree(): void
186:     {
187:         CatalogLock::tree();
188:     }
