16: class AppServiceProvider extends ServiceProvider
17: {
18:     /**
19:      * Register any application services.
20:      */
21:     public function register(): void
22:     {
23:         // scoped لا singleton: ذاكرة المستخدمين لكل طلب تعمل داخل الطلب، ولا
24:         // تتسرب صلاحيات مستخدم لطلب آخر تحت Octane (L-6).
25:         $this->app->scoped(BranchAccess::class);
26:         $this->app->scoped(SettingService::class);
