29:     /**
30:      * Bootstrap any application services.
31:      */
32:     public function boot(): void
33:     {
34:         // أسماء قصيرة ثابتة لمراجع الدفتر (stock_movements.reference_type):
35:         // إعادة تسمية/نقل الكلاسات لاحقًا لا تكسر أثر التدقيق التاريخي.
36:         // الصفوف القديمة المخزنة باسم الكلاس الكامل تظل قابلة للقراءة.
37:         Relation::morphMap([
38:             'stock_transfer' => StockTransfer::class,
39:             'stocktake' => Stocktake::class,
40:         ]);
41: 
42:         // حد دخول العملاء (متجر/جملة): بالمُعرّف (بريد/هاتف) وبالـ IP معًا
43:         RateLimiter::for('customer-login', function (Request $request): array {
44:             $identifier = $request->input('login');
45:             $idKey = is_string($identifier) ? hash('sha256', Str::lower(trim($identifier))) : 'none';
46: 
47:             return [
48:                 Limit::perMinute(5)->by('customer-login-id:'.$idKey),
49:                 Limit::perMinute(30)->by('customer-login-ip:'.($request->ip() ?? 'unknown')),
50:             ];
51:         });
52: 
53:         RateLimiter::for('admin-login', function (Request $request): array {
54:             $email = $request->input('email');
55:             $normalizedEmail = is_string($email)
56:                 ? Str::transliterate(Str::lower(trim($email)))
57:                 : '';
58:             $emailKey = hash('sha256', $normalizedEmail);
59: 
60:             return [
61:                 Limit::perMinute(5)->by('admin-login-email:'.$emailKey),
62:                 Limit::perHour(30)->by('admin-login-email-hour:'.$emailKey),
63:                 Limit::perMinute(120)->by('admin-login-ip:'.($request->ip() ?? 'unknown')),
64:             ];
65:         });
66: 
67:         RateLimiter::for('customer-password-reset', fn (Request $request) => Limit::perMinute(5)
68:             ->by('customer-password-reset:'.($request->ip() ?? 'unknown')));
69:     }
