 17: class ProductService
 18: {
 19:     public function __construct(private ProductPublishabilityChecker $publishability) {}
 20: 
 21:     public function create(array $data, User $user): Product
 22:     {
 23:         return DB::transaction(function () use ($data, $user) {
 24:             CatalogLock::tree(shared: true);
 25:             $variants = $data['variants'] ?? [];
 26:             unset($data['variants']);
 27:             $data = array_filter($data, fn ($value) => $value !== null);
 28: 
 29:             if (($data['status'] ?? 'draft') !== ProductStatus::Draft->value) {
 30:                 throw new BusinessException('يجب إنشاء المنتج كمسودة ثم رفع صوره ونشره', ['status' => ['الحالة المسموحة عند الإنشاء هي draft']]);
 31:             }
 32: 
 33:             $data['slug'] = $data['slug'] ?? SlugService::make(Product::class, $data['name_en']);
 34:             $data['created_by'] = $user->id;
 35:             $data['status'] = ProductStatus::Draft->value; // دايمًا يتعمل draft الأول
 36: 
 37:             // قفل صفوف القسم والبراند بيمنع حذفهم في نفس لحظة إنشاء المنتج عليهم
 38:             $this->lockReference(Category::class, (int) $data['category_id'], 'category_id');
 39:             if (! empty($data['brand_id'])) {
 40:                 $this->lockReference(Brand::class, (int) $data['brand_id'], 'brand_id');
 41:             }
 42: 
 43:             $product = Product::create($data);
 44:             $product->update(['code' => 'P'.str_pad((string) $product->id, 5, '0', STR_PAD_LEFT)]);
 45: 
 46:             foreach ($variants as $v) {
 47:                 app(VariantService::class)->create($product, $v);
 48:             }
 49: 
 50:             return $product->fresh(['category.media', 'brand.media', 'variants.media', 'media']);
 51:         });
 52:     }
 53: 
 54:     public function update(Product $product, array $data, User $user): Product
 55:     {
 56:         return DB::transaction(function () use ($product, $data, $user) {
 57:             CatalogLock::tree(shared: true);
 58:             // قفل صف المنتج طول التعديل عشان فحص النشر ميعديش مع تعديل متزامن
 59:             $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail();
 60: 
 61:             $newStatus = isset($data['status']) ? ProductStatus::from($data['status']) : null;
 62:             unset($data['status']);
 63: 
 64:             if (array_key_exists('slug', $data) && empty($data['slug'])) {
 65:                 $data['slug'] = SlugService::make(Product::class, $data['name_en'] ?? $product->name_en, $product->id);
 66:             }
 67:             $this->lockReference(Category::class, (int) ($data['category_id'] ?? $product->category_id), 'category_id');
 68:             if (! empty($data['brand_id'])) {
 69:                 $this->lockReference(Brand::class, (int) $data['brand_id'], 'brand_id');
 70:             }
 71: 
 72:             if (array_key_exists('is_featured', $data) && $data['is_featured'] === null) {
 73:                 unset($data['is_featured']);
 74:             }
 75: 
 76:             $product->update($data);
 77: 
 78:             if ($newStatus && $newStatus !== $product->status) {
 79:                 $this->changeStatus($product, $newStatus, $user);
 80:             } elseif ($product->status === ProductStatus::Published) {
 81:                 // تعديل من غير تغيير حالة على منتج منشور: القواعد بتتفحص من جديد
 82:                 $this->assertPublishable($product);
 83:             }
 84: 
 85:             return $product->fresh(['category.media', 'brand.media', 'variants.media', 'media']);
 86:         });
 87:     }
 88: 
 89:     public function changeStatus(Product $product, ProductStatus $status, User $user): void
 90:     {
 91:         DB::transaction(function () use ($product, $status, $user): void {
 92:             CatalogLock::tree(shared: true);
 93:             // قفل صف المنتج وقسمه قبل الفحص والنشر، عشان مفيش تعديل متزامن يعدي بين الفحص والحفظ
 94:             $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail();
 95:             if ($product->category_id) {
 96:                 $this->lockReference(Category::class, (int) $product->category_id, 'category_id');
 97:             }
 98:             $product->refresh();
 99: 
100:             if ($product->status !== $status && ($product->status === ProductStatus::Published || $status === ProductStatus::Published) && ! $user->can('products.publish')) {
101:                 throw new BusinessException('ليس لديك صلاحية تغيير نشر المنتجات', [], 403);
102:             }
103: 
104:             if ($status === ProductStatus::Published) {
105:                 $this->assertPublishable($product);
106:                 $product->published_at ??= now();
107:             }
108:             $product->status = $status;
109:             $product->save();
110:         });
111:         $product->refresh();
112:     }
113: 
114:     public function assertPublishable(Product $product): void
115:     {
116:         $this->publishability->assertPublishable($product);
117:     }
118: 
119:     private function lockReference(string $model, int $id, string $field): void
120:     {
121:         if (! $model::whereKey($id)->sharedLock()->first()) {
122:             throw new BusinessException('أحد المراجع المطلوبة لم يعد متاحًا', [$field => ['القيمة المحددة غير موجودة أو محذوفة']]);
123:         }
124:     }
125: 
126:     public function delete(Product $product): void
127:     {
128:         DB::transaction(function () use ($product): void {
129:             $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail();
130:             // حذف المنتج يحذف متغيراته ناعمًا: أي رصيد على أي منها يُحبس (M-9)
131:             if (StockLevel::query()->whereIn('product_variant_id', $product->variants()->pluck('id'))
132:                 ->where(fn ($q) => $q->where('on_hand', '<>', 0)->orWhere('reserved', '<>', 0)
133:                     ->orWhere('damaged', '<>', 0)->orWhere('in_transit', '<>', 0))
134:                 ->exists()) {
135:                 throw new BusinessException('لا يمكن حذف منتج له متغيرات برصيد مخزون؛ صفِّ الأرصدة أولًا.');
136:             }
137:             $product->variants()->delete();  // soft
138:             $product->delete();              // soft
139:         });
140:         // TODO مرحلة الطلبات: منع الحذف لو المنتج عليه طلبات، وبدل كده يتعمل archived
141:     }
