 15: class VariantService
 16: {
 17:     public function __construct(private ProductPublishabilityChecker $publishability) {}
 18: 
 19:     public function create(Product $product, array $data): ProductVariant
 20:     {
 21:         $data = array_filter($data, fn ($value) => $value !== null);
 22: 
 23:         return DB::transaction(function () use ($product, $data) {
 24:             $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail(); // منع تكرار الترقيم
 25:             $this->assertUniqueCombination($product, $data);
 26: 
 27:             if (empty($data['sku'])) {
 28:                 $seq = $product->variants()->withTrashed()->count() + 1;
 29:                 do {
 30:                     $sku = $product->code.'-'.str_pad((string) $seq, 2, '0', STR_PAD_LEFT);
 31:                     $seq++;
 32:                 } while (ProductVariant::withTrashed()->where('sku', $sku)->exists());
 33:                 $data['sku'] = $sku;
 34:             }
 35: 
 36:             $variant = $product->variants()->create($data);
 37: 
 38:             if (empty($variant->barcode)) {
 39:                 $variant->update(['barcode' => BarcodeGenerator::fromId($variant->id)]);
 40:             }
 41: 
 42:             // متغير جديد على منتج منشور لازم ميكسرش قواعد النشر، وإلا التعديل كله يتلغي
 43:             if ($product->status === ProductStatus::Published) {
 44:                 $this->publishability->assertPublishable($product);
 45:             }
 46: 
 47:             return $variant;
 48:         });
 49:     }
 50: 
 51:     public function update(ProductVariant $variant, array $data): ProductVariant
 52:     {
 53:         foreach (['cost_price', 'reorder_level', 'sort_order', 'is_active'] as $field) {
 54:             if (array_key_exists($field, $data) && $data[$field] === null) {
 55:                 unset($data[$field]);
 56:             }
 57:         }
 58: 
 59:         return DB::transaction(function () use ($variant, $data) {
 60:             $product = Product::whereKey($variant->product_id)->lockForUpdate()->firstOrFail();
 61:             $variant = $product->variants()->whereKey($variant->id)->firstOrFail();
 62:             $this->assertUniqueCombination($product, array_merge($variant->only(['color_name_en', 'size', 'capacity']), $data), $variant->id);
 63: 
 64:             if (array_key_exists('is_active', $data) && ! $data['is_active']) {
 65:                 $this->assertNotLastActiveOfPublished($variant);
 66:             }
 67:             if (array_key_exists('barcode', $data) && blank($data['barcode'])) {
 68:                 $data['barcode'] = BarcodeGenerator::fromId($variant->id);
 69:             }
 70:             $variant->update($data);
 71: 
 72:             // أي تعديل على متغير منتج منشور بيعيد فحص قواعد النشر جوه نفس الـ transaction
 73:             if ($product->status === ProductStatus::Published) {
 74:                 $this->publishability->assertPublishable($product);
 75:             }
 76: 
 77:             return $variant->fresh(['media', 'product']);
 78:         });
 79:     }
 80: 
 81:     public function delete(ProductVariant $variant): void
 82:     {
 83:         DB::transaction(function () use ($variant): void {
 84:             $product = Product::whereKey($variant->product_id)->lockForUpdate()->firstOrFail();
 85:             $variant = $product->variants()->whereKey($variant->id)->firstOrFail();
 86:             $this->assertNotLastActiveOfPublished($variant);
 87:             // متغير له رصيد في أي وعاء لا يُحذف: الحذف الناعم كان يحبس الرصيد
 88:             // لأن فحوص وجود المتغير تستبعد المحذوف (M-9). صفِّ الرصيد أولًا.
 89:             if (StockLevel::query()->where('product_variant_id', $variant->id)
 90:                 ->where(fn ($q) => $q->where('on_hand', '<>', 0)->orWhere('reserved', '<>', 0)
 91:                     ->orWhere('damaged', '<>', 0)->orWhere('in_transit', '<>', 0))
 92:                 ->exists()) {
 93:                 throw new BusinessException('لا يمكن حذف متغير له رصيد مخزون؛ صفِّ رصيده أولًا أو عطّله بدلًا من حذفه.');
 94:             }
 95:             $variant->delete();
 96: 
 97:             if ($product->status === ProductStatus::Published) {
 98:                 $this->publishability->assertPublishable($product);
 99:             }
100:         });
101:     }
102: 
103:     private function assertUniqueCombination(Product $product, array $d, ?int $ignoreId = null): void
104:     {
105:         // المقارنة من غير حساسية لحالة الحروف: Black وblack نفس اللون
106:         $matchField = fn ($q, string $column, ?string $value) => $value === null
107:             ? $q->whereNull($column)
108:             : $q->whereRaw("lower({$column}) = ?", [mb_strtolower($value)]);
109: 
110:         $exists = $product->variants()
111:             ->when($ignoreId, fn ($q) => $q->where('id', '!=', $ignoreId))
112:             ->where(fn ($q) => $matchField($q, 'color_name_en', $d['color_name_en'] ?? null))
113:             ->where(fn ($q) => $matchField($q, 'size', $d['size'] ?? null))
114:             ->where(fn ($q) => $matchField($q, 'capacity', $d['capacity'] ?? null))
115:             ->exists();
116:         if ($exists) {
117:             throw new BusinessException('يوجد متغير بنفس اللون والمقاس والسعة لهذا المنتج');
118:         }
119:     }
120: 
121:     private function assertNotLastActiveOfPublished(ProductVariant $variant): void
122:     {
123:         $product = $variant->product;
124:         if ($product->status === ProductStatus::Published
125:             && $product->variants()->where('is_active', true)->where('id', '!=', $variant->id)->doesntExist()) {
126:             throw new BusinessException('لا يمكن حذف/تعطيل آخر متغير نشط في منتج منشور');
127:         }
128:     }
