 14: class SettingService
 15: {
 16:     /** @var array<string, array{0: string, 1: int}> بادئة وحشو الترقيم لكل نوع — يُقرآن مرة واحدة لكل طلب (M11). */
 17:     private array $numberingConfig = [];
 18: 
 19:     private const CACHE_KEY = 'app_settings_static';
 20: 
 21:     private const CACHE_TTL_SECONDS = 3600;
 22: 
 23:     /** @var list<string> */
 24:     private const NUMBERING_COUNTER_KEYS = [
 25:         'invoice_next_number',
 26:         'order_next_number',
 27:         'purchase_order_next_number',
 28:         'quotation_next_number',
 29:         'movement_next_number',
 30:         'transfer_next_number',
 31:         'stocktake_next_number',
 32:     ];
 33: 
 34:     /**
 35:      * Return all settings grouped by their group name, with values cast to their declared types.
 36:      * Numbering counters are read fresh because they change for every generated document number.
 37:      *
 38:      * @return array<string, array<string, mixed>>
 39:      */
 40:     public function getAllGrouped(): array
 41:     {
 42:         $grouped = Cache::remember(self::CACHE_KEY, self::CACHE_TTL_SECONDS, function (): array {
 43:             return Setting::query()
 44:                 ->whereNotIn('key', self::NUMBERING_COUNTER_KEYS)
 45:                 ->orderBy('group')
 46:                 ->orderBy('key')
 47:                 ->get()
 48:                 ->groupBy('group')
 49:                 ->map(fn ($settings): array => $settings
 50:                     ->mapWithKeys(fn (Setting $setting): array => [
 51:                         $setting->key => $this->castValue($setting->value, $setting->type),
 52:                     ])
 53:                     ->all())
 54:                 ->all();
 55:         });
 56: 
 57:         $counters = Setting::query()
 58:             ->whereIn('key', self::NUMBERING_COUNTER_KEYS)
 59:             ->orderBy('key')
 60:             ->get()
 61:             ->mapWithKeys(fn (Setting $setting): array => [
 62:                 $setting->key => $this->castValue($setting->value, $setting->type),
 63:             ])
 64:             ->all();
 65: 
 66:         if (isset($counters['movement_next_number'])) {
 67:             $counters['movement_next_number'] = $this->nextMovementNumber();
 68:         }
 69: 
 70:         if ($counters !== []) {
 71:             $grouped['numbering'] = array_merge($grouped['numbering'] ?? [], $counters);
 72:             ksort($grouped['numbering']);
 73:         }
 74: 
 75:         return $grouped;
 76:     }
 77: 
 78:     public function get(string $key, mixed $default = null): mixed
 79:     {
 80:         foreach ($this->getAllGrouped() as $settings) {
 81:             if (array_key_exists($key, $settings)) {
 82:                 return $settings[$key];
 83:             }
 84:         }
 85: 
 86:         return $default;
 87:     }
 88: 
 89:     /**
 90:      * Update a flat key/value map atomically and invalidate the cached settings after commit.
 91:      *
 92:      * @param  array<string, mixed>  $settings
 93:      *
 94:      * @throws JsonException
 95:      */
 96:     public function updateBatch(array $settings): void
 97:     {
 98:         DB::transaction(function () use ($settings): void {
 99:             $movementSequenceTarget = null;
100:             $lockedSettings = Setting::query()
101:                 ->whereIn('key', array_keys($settings))
102:                 ->orderBy('key')
103:                 ->lockForUpdate()
104:                 ->get()
105:                 ->keyBy('key');
106: 
107:             $missingKeys = array_diff(array_keys($settings), $lockedSettings->keys()->all());
108: 
109:             if ($missingKeys !== []) {
110:                 throw new InvalidArgumentException('Settings are not initialized: '.implode(', ', $missingKeys));
111:             }
112: 
113:             foreach ($settings as $key => $value) {
114:                 /** @var Setting $setting */
115:                 $setting = $lockedSettings->get($key);
116: 
117:                 if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
118:                     $value = max($this->counterValue($setting->value), $this->counterValue($value));
119:                     if ($key === 'movement_next_number') {
120:                         $value = max($value, $this->nextMovementNumber());
121:                         $movementSequenceTarget = $value;
122:                     }
123:                 }
124: 
125:                 $setting->value = $value === null && str_ends_with($key, '_prefix')
126:                     ? ''
127:                     : $this->serializeValue($value, $setting->type);
128:                 $setting->save();
129:             }
130: 
131:             DB::afterCommit(fn () => $this->clearCache());
132: 
133:             if ($movementSequenceTarget !== null) {
134:                 // مزامنة التسلسل بعد الاعتماد لا داخله: ALTER SEQUENCE داخل
135:                 // المعاملة كان يحجب كل nextval (أي كل حركات المخزون) حتى نهاية
136:                 // معاملة الإعدادات (L-9). الدالة تقفل الترقيم لمدة الاستعلام
137:                 // نفسه وتنسّق رفع الحد الأدنى مع كل تخصيص جديد لمنع إعادة رقم.
138:                 DB::afterCommit(function () use ($movementSequenceTarget): void {
139:                     DB::selectOne('SELECT inventory_movement_number(?) AS number', [$movementSequenceTarget]);
140:                 });
141:             }
142:         }, attempts: 3);
143:     }
144: 
145:     /**
146:      * Atomically return and increment the next document number for the requested type.
147:      *
148:      * @throws JsonException
149:      */
150:     public function generateNextNumber(string $type): string
151:     {
152:         if ($type === 'movement') {
153:             [$prefix, $padding] = $this->numberingConfig('movement', 'movement_prefix', 'movement_padding');
154:             $number = DB::selectOne('SELECT inventory_movement_number() AS number')->number;
155: 
156:             return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
157:         }
158:         $definitions = [
159:             'invoice' => ['prefix' => 'invoice_prefix', 'next' => 'invoice_next_number', 'padding' => 'invoice_padding'],
160:             'order' => ['prefix' => 'order_prefix', 'next' => 'order_next_number', 'padding' => 'order_padding'],
161:             'purchase_order' => ['prefix' => 'purchase_order_prefix', 'next' => 'purchase_order_next_number', 'padding' => 'purchase_order_padding'],
162:             'quotation' => ['prefix' => 'quotation_prefix', 'next' => 'quotation_next_number', 'padding' => 'quotation_padding'],
163:             'transfer' => ['prefix' => 'transfer_prefix', 'next' => 'transfer_next_number', 'padding' => 'transfer_padding'],
164:             'stocktake' => ['prefix' => 'stocktake_prefix', 'next' => 'stocktake_next_number', 'padding' => 'stocktake_padding'],
165:         ];
166: 
167:         if (! isset($definitions[$type])) {
168:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
169:         }
170: 
171:         $definition = $definitions[$type];
172:         [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);
173: 
174:         return DB::transaction(function () use ($definition, $prefix, $padding): string {
175:             // العداد وحده يُقفل ويُقرأ طازجًا كل مرة؛ البادئة والحشو من ذاكرة الطلب.
176:             $nextSetting = Setting::query()
177:                 ->where('key', $definition['next'])
178:                 ->lockForUpdate()
179:                 ->first();
180: 
181:             if ($nextSetting === null) {
182:                 throw new InvalidArgumentException("Required numbering setting [{$definition['next']}] is missing.");
183:             }
184: 
185:             $nextValue = $this->counterValue($nextSetting->value);
186: 
187:             $formatted = $prefix.str_pad((string) $nextValue, $padding, '0', STR_PAD_LEFT);
188:             $nextSetting->value = (string) ($nextValue + 1);
189:             $nextSetting->save();
190: 
191:             return $formatted;
192:         }, attempts: 3);
193:     }
194: 
195:     /**
196:      * بادئة وحشو نوع ترقيم — قراءة واحدة لكل طلب بدل استعلام مع كل حركة/مستند.
197:      *
198:      * @return array{0: string, 1: int}
199:      */
200:     private function numberingConfig(string $type, string $prefixKey, string $paddingKey): array
201:     {
202:         return $this->numberingConfig[$type] ??= (function () use ($prefixKey, $paddingKey): array {
203:             $settings = Setting::query()->whereIn('key', [$prefixKey, $paddingKey])->pluck('value', 'key');
204: 
205:             foreach ([$prefixKey, $paddingKey] as $key) {
206:                 if (! $settings->has($key)) {
207:                     throw new InvalidArgumentException("Required numbering setting [{$key}] is missing.");
208:                 }
209:             }
210: 
211:             return [(string) $settings[$prefixKey], max(0, (int) $settings[$paddingKey])];
212:         })();
213:     }
214: 
215:     public function clearCache(): void
216:     {
217:         Cache::forget(self::CACHE_KEY);
218:         $this->numberingConfig = [];
219:     }
220: 
221:     private function nextMovementNumber(): int
222:     {
223:         $sequence = DB::selectOne('SELECT last_value, is_called FROM stock_movement_number_seq');
224: 
225:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
226:     }
227: 
228:     private function counterValue(mixed $value): int
229:     {
230:         $number = (is_int($value) || is_string($value))
231:             ? filter_var($value, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1, 'max_range' => PHP_INT_MAX - 1]])
232:             : false;
233:         if ($number === false) {
234:             throw new BusinessException('قيمة عداد الترقيم يجب أن تكون عددًا صحيحًا موجبًا ضمن النطاق المسموح');
235:         }
236: 
237:         return $number;
238:     }
239: 
240:     private function castValue(?string $value, string $type): mixed
241:     {
242:         if ($value === null) {
243:             return null;
244:         }
245: 
246:         return match ($type) {
247:             'boolean' => filter_var($value, FILTER_VALIDATE_BOOLEAN),
248:             'integer' => (int) $value,
249:             'float' => (float) $value,
250:             'json' => json_decode($value, true, 512, JSON_THROW_ON_ERROR),
251:             default => $value,
252:         };
253:     }
254: 
255:     /** @throws JsonException */
256:     private function serializeValue(mixed $value, string $type): ?string
257:     {
258:         if ($value === null) {
259:             return null;
260:         }
261: 
262:         if ($type === 'json') {
263:             return json_encode($value, JSON_THROW_ON_ERROR);
264:         }
265: 
266:         if ($type === 'boolean') {
267:             return filter_var($value, FILTER_VALIDATE_BOOLEAN) ? '1' : '0';
268:         }
269: 
270:         return (string) $value;
271:     }
